import{f as o,o as t,c as d,a2 as a}from"./chunks/framework.Cd9rfTEn.js";const C=JSON.parse('{"title":"Casos de prueba de aceptación — M05 FAC — Facturación: ciclos, lotes y comprobantes","description":"","frontmatter":{},"headers":[],"relativePath":"entregables-analisis-diseno/20-casos-prueba/M05-FAC-facturacion.md","filePath":"entregables-analisis-diseno/20-casos-prueba/M05-FAC-facturacion.md","lastUpdated":null}'),c={name:"entregables-analisis-diseno/20-casos-prueba/M05-FAC-facturacion.md"};function r(i,e,n,s,l,u){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="casos-de-prueba-de-aceptacion-—-m05-fac-—-facturacion-ciclos-lotes-y-comprobantes" tabindex="-1">Casos de prueba de aceptación — M05 FAC — Facturación: ciclos, lotes y comprobantes <a class="header-anchor" href="#casos-de-prueba-de-aceptacion-—-m05-fac-—-facturacion-ciclos-lotes-y-comprobantes" aria-label="Permalink to &quot;Casos de prueba de aceptación — M05 FAC — Facturación: ciclos, lotes y comprobantes&quot;">​</a></h1><p>Parte de <a href="./../20-casos-prueba"><code>20-casos-prueba.md</code></a> (artefacto 9.2). Fuente: <a href="./../../especificacion/anexos/M05-FAC-facturacion"><code>M05-FAC-facturacion.md</code></a> (solo lectura). Generado por <code>_trabajo/gen_casos_prueba.py</code> y revisado; ante diferencias prevalece el anexo.</p><p>Resumen: 179 CP de requisitos funcionales, 3 CP de escenarios ESC y 22 CP de casos de uso CU.</p><p>Convenciones: el formato Dado / Cuando / Entonces sigue <code>07-estrategia-pruebas.md</code> §13; la ola de un CP de RF es la del prompt que lo implementa en <code>03</code> (prevalece sobre la columna del anexo); la de un CP de escenario es la última ola de los RF que cita o la que el escenario declara. Prioridad Extensión del anexo se agrupa como Estándar. Todos los datos son ficticios (TEN-001, TEN-002 y semillas del §18 del anexo).</p><h2 id="_1-casos-por-requisito-funcional" tabindex="-1">1. Casos por requisito funcional <a class="header-anchor" href="#_1-casos-por-requisito-funcional" aria-label="Permalink to &quot;1. Casos por requisito funcional&quot;">​</a></h2><p>Precondiciones comunes de esta sección: ola indicada desplegada en <code>staging</code> o <code>sandbox</code>; tenant ficticio TEN-001 con la configuración publicada y las semillas del M05 §18; usuario con la capability que exige el RF (el caso negativo sin capability lo cubre la suite de permisos negativos, <code>07</code> §4.3). Resultado esperado: el criterio de aceptación del RF se cumple, la prueba automatizada cita el RF y el CP en su nombre, y quedan auditoría y evento cuando hay cambio persistente.</p><h3 id="_1-1-ciclos-universos-y-plantillas-m05-§5-1" tabindex="-1">1.1 Ciclos, universos y plantillas (M05 §5.1) <a class="header-anchor" href="#_1-1-ciclos-universos-y-plantillas-m05-§5-1" aria-label="Permalink to &quot;1.1 Ciclos, universos y plantillas (M05 §5.1)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0001</td><td>RF-FAC-001; M05 §5.1; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Ciclos: <code>AG-C1</code> agua (corte día 5), <code>AG-C2</code> agua (día 20), <code>ELE-C1</code> electricidad (día 10) <code>GAS-C1</code> gas (día 15, bimestral)</td><td>Crear ciclos de facturación por tenant, servicio y universo, con vigencia, periodicidad (mensual, bimestral, trimestral, anual, a demanda) y calendario con fechas diferenciadas: corte de consumo, fin de período facturado, ejecución del…</td><td>TEN-001 tiene AG-C1 (corte día 5) y AG-C2 (día 20) para agua y ELE-C1 (día 10) para electricidad; TEN-002 tiene GAS-C1 (día 15); ninguno ve ni afecta al otro.</td></tr><tr><td>CP-FAC-0002</td><td>RF-FAC-002; M05 §5.1; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Ciclos: <code>AG-C1</code> agua (corte día 5), <code>AG-C2</code> agua (día 20), <code>ELE-C1</code> electricidad (día 10) <code>GAS-C1</code> gas (día 15, bimestral)</td><td>Permitir uno o más ciclos por servicio, cada uno con su universo.</td><td>Dos ciclos de agua coexisten con universos disjuntos.</td></tr><tr><td>CP-FAC-0003</td><td>RF-FAC-003; M05 §5.1; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Universos: <code>GRUPO-CENTRO</code>, <code>GRUPO-NORTE</code>, <code>CONTROL</code> (10 cuentas) <code>GAS-TODOS</code></td><td>Definir universos por criterios combinables: zona, sector y recorrido de lectura; ruta; conjunto de facturación; zona postal, empresa postal y localidad postal; categoría; plan; grupo de facturación; condición fiscal; altas anteriores a…</td><td>Un universo &quot;Grupo Centro&quot; por zona devuelve la misma pertenencia al consultarlo dos veces con los mismos datos.</td></tr><tr><td>CP-FAC-0004</td><td>RF-FAC-004; M05 §5.1; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Ciclos: <code>AG-C1</code> agua (corte día 5), <code>AG-C2</code> agua (día 20), <code>ELE-C1</code> electricidad (día 10) <code>GAS-C1</code> gas (día 15, bimestral)</td><td>Controlar pertenencia y solapamientos: un contrato-servicio pertenece a un solo ciclo vigente por servicio en cada período; al publicar un ciclo o universo se informa y bloquea todo solapamiento.</td><td>Publicar un universo que incluye un contrato ya cubierto por otro ciclo vigente falla con la lista de contratos en conflicto.</td></tr><tr><td>CP-FAC-0005</td><td>RF-FAC-005; M05 §5.1; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Registrar cambios de pertenencia con fecha efectiva y fecha de registro; un cambio rige desde el período siguiente al último corte procesado, sin reabrir lotes emitidos.</td><td>Un contrato movido de AG-C1 a AG-C2 el día 12 se factura en AG-C2 desde el período siguiente y no queda sin facturar ni facturado dos veces.</td></tr><tr><td>CP-FAC-0006</td><td>RF-FAC-006; M05 §5.1; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Ciclos: <code>AG-C1</code> agua (corte día 5), <code>AG-C2</code> agua (día 20), <code>ELE-C1</code> electricidad (día 10) <code>GAS-C1</code> gas (día 15, bimestral)</td><td>Resolver las fechas del ciclo con el calendario del tenant (T04): días hábiles, feriados nacionales, provinciales y locales, meses cortos, años bisiestos; regla de desplazamiento al siguiente o anterior día hábil por tipo de fecha.</td><td>Un vencimiento calculado en domingo o feriado se desplaza según la regla; el 29/02 se resuelve sin error.</td></tr><tr><td>CP-FAC-0007</td><td>RF-FAC-007; M05 §5.1; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Expresar las fechas de la plantilla de forma declarativa (&quot;día hábil N del mes&quot;, &quot;fin de mes + N días&quot;, &quot;N días desde emisión&quot;, &quot;fecha fija&quot;) y resolverlas al preparar el lote, guardando el valor resuelto en el lote.</td><td>La plantilla guarda la expresión; el lote guarda la fecha concreta; cambiar la plantilla no altera lotes ya preparados.</td></tr><tr><td>CP-FAC-0008</td><td>RF-FAC-008; M05 §5.1; PRO-O4-08</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Programación automática: según el calendario del ciclo, el sistema crea el lote en borrador en la fecha de ejecución y notifica al responsable. Nunca prepara ni emite sin una acción o aprobación humana configurada.</td><td>En la fecha de ejecución aparece el lote borrador en la bandeja del responsable; no hay comprobantes nuevos hasta su aprobación.</td></tr><tr><td>CP-FAC-0009</td><td>RF-FAC-009; M05 §5.1; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Mantener <strong>plantillas de corrida</strong> versionadas, separadas del tipo de factura comercial: servicios con período por servicio y rango de lecturas, filtros de universo, cuotas a incluir, reglas de vencimiento y próximo vencimiento, tipo de…</td><td>Publicar una versión nueva de plantilla no modifica lotes preparados con la anterior.</td></tr><tr><td>CP-FAC-0010</td><td>RF-FAC-010; M05 §5.1; PRO-O4-08</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Proponer la próxima fecha de facturación: último día del mes + 10 días, o un mes después de la última facturación de la plantilla si fue hace menos de 60 días; editable.</td><td>Con última facturación el 10/10/2026 la propuesta es 10/11/2026.</td></tr><tr><td>CP-FAC-0011</td><td>RF-FAC-011; M05 §5.1; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Registrar marcas de <strong>no facturar</strong> por cuenta o contrato con vigencia, motivo, usuario de alta y de baja, y la marca por servicio de &quot;no facturar&quot;; los casos marcados quedan excluidos del universo con su causa.</td><td>Una cuenta con marca activa aparece en el lote como &quot;excluida: marca no facturar&quot; y no genera comprobante.</td></tr><tr><td>CP-FAC-0012</td><td>RF-FAC-012; M05 §5.1; PRO-O4-08</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Mantener <strong>clasificaciones comerciales</strong> de comprobante (tipo de factura: energía, financiación, servicios generales, viviendas, prepaga) con su reporte, plan de cuentas asociado y grupo de talón.</td><td>Cada comprobante emitido tiene una clasificación comercial y una plantilla de impresión resoluble.</td></tr></tbody></table><h3 id="_1-2-lote-preparar-y-congelar-el-universo-m05-§5-2" tabindex="-1">1.2 Lote: preparar y congelar el universo (M05 §5.2) <a class="header-anchor" href="#_1-2-lote-preparar-y-congelar-el-universo-m05-§5-2" aria-label="Permalink to &quot;1.2 Lote: preparar y congelar el universo (M05 §5.2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0013</td><td>RF-FAC-013; M05 §5.2; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Universos: <code>GRUPO-CENTRO</code>, <code>GRUPO-NORTE</code>, <code>CONTROL</code> (10 cuentas) <code>GAS-TODOS</code></td><td>Crear un lote desde un ciclo o ad hoc indicando: a quién (todas las cuentas del universo, una cuenta, varias cuentas, cuentas de control), servicios y período por servicio, período general y secuencia, tipo de comprobante y tipo de…</td><td>Las cuatro modalidades de destinatarios generan universos con la cantidad esperada.</td></tr><tr><td>CP-FAC-0014</td><td>RF-FAC-014; M05 §5.2; PRO-O4-08</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Universos: <code>GRUPO-CENTRO</code>, <code>GRUPO-NORTE</code>, <code>CONTROL</code> (10 cuentas) <code>GAS-TODOS</code></td><td>Importar la lista de cuentas de un lote &quot;varias cuentas&quot; desde Excel con el asistente genérico (subir, previsualizar errores, confirmar).</td><td>Una planilla con una cuenta inexistente muestra el error en la previsualización y no se incorpora.</td></tr><tr><td>CP-FAC-0015</td><td>RF-FAC-015; RN-FAC-008, RN-FAC-016; M05 §5.2; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Validar la configuración del lote antes de preparar con todas las reglas RN-FAC-008 a RN-FAC-016.</td><td>Un lote con Vto2 anterior a Vto1 no se puede preparar y muestra el error en el campo.</td></tr><tr><td>CP-FAC-0016</td><td>RF-FAC-016; M05 §5.2; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Validar datos y prerrequisitos: conceptos obligatorios configurados (PRM-FAC-060), matriz de comprobantes resoluble para cada condición fiscal y para ambos signos, numeración forzada inexistente.</td><td>Si para &quot;Exento&quot; no hay comprobante de crédito resoluble, la preparación se detiene con &quot;Verifique el tipo de comprobante para la condición fiscal Exento&quot;.</td></tr><tr><td>CP-FAC-0017</td><td>RF-FAC-017; M05 §5.2; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Verificar prerrequisitos fiscales y de estado consultando a M06 y M17: CESP vigente si algún servicio liquida como servicio público, padrón de Ingresos Brutos vigente, comprobantes pendientes de autorización con antigüedad mayor a…</td><td>Sin CESP vigente un lote de servicio público no pasa a &quot;preparado&quot;; con override aprobado sí, y queda auditado.</td></tr><tr><td>CP-FAC-0018</td><td>RF-FAC-018; M05 §5.2; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Garantizar exclusión mutua: un solo lote en preparación, prefacturación o emisión por (tenant, ciclo o plantilla, período, secuencia); lotes de distintos ciclos pueden correr en paralelo.</td><td>Un segundo intento de emitir el mismo ciclo y período responde 409 con el lote en curso.</td></tr><tr><td>CP-FAC-0019</td><td>RF-FAC-019; M05 §5.2; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td><strong>Preparar</strong> congela el universo: guarda la foto de la selección (cuentas, contratos, servicios, grupos), las cantidades (consumos aprobados con su id y versión), las versiones de reglas aplicables (tarifa, configuración publicada…</td><td>Re-ejecutar la prefacturación de un lote preparado produce los mismos importes aunque después se publique una tarifa nueva.</td></tr><tr><td>CP-FAC-0020</td><td>RF-FAC-020; RN-FAC-020, RN-FAC-026; M05 §5.2; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Ciclos: <code>AG-C1</code> agua (corte día 5), <code>AG-C2</code> agua (día 20), <code>ELE-C1</code> electricidad (día 10) <code>GAS-C1</code> gas (día 15, bimestral)</td><td>Aplicar las reglas de elegibilidad por servicio (RN-FAC-020 a RN-FAC-026): conectado, consumos sin facturar, cargos pendientes, baja con cobro proporcional, prepaga, altas anteriores, período no facturado.</td><td>Un servicio dado de baja hace más de 6 meses sin cargos pendientes no entra en el universo.</td></tr><tr><td>CP-FAC-0021</td><td>RF-FAC-021; M05 §5.2; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Impedir la doble facturación con el registro <code>billedPeriods</code> por (contrato, servicio, período, secuencia) vigente; solo se vuelve a facturar con otra secuencia explícita o por consumos/cargos nuevos.</td><td>Emitir dos veces el mismo lote produce 0 comprobantes nuevos en la segunda ejecución.</td></tr><tr><td>CP-FAC-0022</td><td>RF-FAC-022; M05 §5.2; PRO-O4-08</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Versionar el universo: agregar o quitar casos después de preparar genera una versión nueva con las diferencias y su motivo; nunca se reemplaza en silencio.</td><td>El lote muestra &quot;Universo v2: +3 −1, motivo: altas tardías aprobadas&quot;.</td></tr><tr><td>CP-FAC-0023</td><td>RF-FAC-023; M05 §5.2; PRO-O4-08</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Universos: <code>GRUPO-CENTRO</code>, <code>GRUPO-NORTE</code>, <code>CONTROL</code> (10 cuentas) <code>GAS-TODOS</code></td><td>Seleccionar una <strong>muestra de control</strong> automática: una cuenta por categoría, una por condición fiscal, una de grandes y otra de pequeños consumos, más las que el usuario agregue; se marca en el lote para su revisión.</td><td>Con 5 categorías y 3 condiciones fiscales la muestra tiene al menos 8 cuentas distintas cuando existen.</td></tr><tr><td>CP-FAC-0024</td><td>RF-FAC-024; M05 §5.2; PRO-O4-08</td><td>O4</td><td>Estándar</td><td>regla</td><td>TEN-001 con Universos: <code>GRUPO-CENTRO</code>, <code>GRUPO-NORTE</code>, <code>CONTROL</code> (10 cuentas) <code>GAS-TODOS</code></td><td>Clonar un lote anterior como base de uno nuevo (servicios, filtros, cuentas, opciones), recalculando fechas.</td><td>Clonar el lote de octubre crea un borrador de noviembre con los mismos filtros.</td></tr><tr><td>CP-FAC-0175</td><td>RF-FAC-175; RN-FAC-155, RN-TAR-015; M05 §5.2; PRO-O7-07</td><td>O7</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Ordenar la preparación y prefacturación por <strong>dependencias entre servicios relacionados</strong>: un servicio que toma el consumo de otro (ej. CLO sobre AG, RN-TAR-015) se procesa después de que su servicio base esté preparado con consumo…</td><td>En un lote AG + CLO, CLO de cada cuenta se calcula después de AG; una cuenta con AG dado de baja queda excluida con <code>RELATED_SERVICE_MISSING</code> y las demás se emiten.</td></tr></tbody></table><h3 id="_1-3-prefacturacion-simulacion-y-comparacion-m05-§5-3" tabindex="-1">1.3 Prefacturación, simulación y comparación (M05 §5.3) <a class="header-anchor" href="#_1-3-prefacturacion-simulacion-y-comparacion-m05-§5-3" aria-label="Permalink to &quot;1.3 Prefacturación, simulación y comparación (M05 §5.3)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0025</td><td>RF-FAC-025; M05 §5.3; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Prefacturar cada caso invocando el motor de M04 con las versiones congeladas; obtener comprobantes candidatos en borrador con detalle de cálculo, sin numerar, sin consumir ítems y sin afectar saldos.</td><td>Tras prefacturar, la cuenta corriente (M07) no registra ningún movimiento.</td></tr><tr><td>CP-FAC-0026</td><td>RF-FAC-026; M05 §5.3; PRO-O4-09</td><td>O4</td><td>Estándar</td><td>regla</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Simular servicios puntuales con configuración genérica (todo vence hoy, lecturas de los últimos dos meses) y simular una cuenta con un cuadro tarifario forzado para comparar cuadros.</td><td>La simulación con cuadro forzado muestra ambos totales y la diferencia.</td></tr><tr><td>CP-FAC-0027</td><td>RF-FAC-027; M05 §5.3; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Tramas: <code>TR-AG</code> 2 vencimientos, 3 % fijo; <code>TR-ELE</code> 3 vencimientos por rango de importe <code>TR-GAS</code> 2 vencimientos, % diario</td><td>Comparar el resultado contra el período anterior por caso, servicio, categoría y total; marcar variaciones que superen <code>PRM-FAC-030</code> (porcentaje) o <code>PRM-FAC-031</code> (importe) como advertencias.</td><td>Un caso que pasa de ARS 13.000 a ARS 40.000 aparece como advertencia de variación.</td></tr><tr><td>CP-FAC-0028</td><td>RF-FAC-028; M05 §5.3; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Armar comprobantes candidatos agrupando por (titular/cuenta, grupo de facturación) según la modalidad vigente; un servicio marcado &quot;facturar con otros&quot; solo se incluye si el comprobante tiene ítems de otro servicio; los cargos que una…</td><td>Un servicio &quot;con otros&quot; solo en la cuenta no genera comprobante.</td></tr><tr><td>CP-FAC-0029</td><td>RF-FAC-029; M05 §5.3; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Tramas: <code>TR-AG</code> 2 vencimientos, 3 % fijo; <code>TR-ELE</code> 3 vencimientos por rango de importe <code>TR-GAS</code> 2 vencimientos, % diario</td><td>Aplicar el criterio de emisión: se emite si algún renglón tiene importe distinto de cero; por servicio, opcionalmente, se emite en cero cuando hay consumos (<code>PRM-FAC-032</code>).</td><td>Con el parámetro apagado, un caso con importe 0 queda &quot;sin cargo&quot; en el lote y no emite.</td></tr><tr><td>CP-FAC-0030</td><td>RF-FAC-030; M05 §5.3; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Tratar el total negativo según la política del servicio: emitir nota de crédito o, para generación distribuida, agregar un renglón &quot;Crédito por energía inyectada&quot; como anticipo a futuro que neutraliza el total (el saldo a favor lo…</td><td>Un caso de GD que da −ARS 2.000 emite comprobante en 0 con crédito de ARS 2.000 a favor.</td></tr><tr><td>CP-FAC-0031</td><td>RF-FAC-031; M05 §5.3; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Ejecutar el pipeline de armado en el orden: cargos adicionales no finales (M04), agrupación, criterio de emisión, cabecera e ítems, resolución de comprobante, signo, punto de venta, cargos finales sobre el comprobante armado (M04), GD…</td><td>El detalle del candidato muestra los pasos aplicados en ese orden.</td></tr><tr><td>CP-FAC-0032</td><td>RF-FAC-032; RN-FAC-040, RN-FAC-044; M05 §5.3; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Resolver el tipo de comprobante con un servicio puro y testeable (RN-FAC-040 a RN-FAC-044). El tipo surge de la condición del emisor y receptor y de la normativa, no de la preferencia del usuario.</td><td>Un caso configurado para factura A sin CUIT queda &quot;No apto para emisión: falta CUIT del receptor&quot; y no se cambia a B sin validación.</td></tr><tr><td>CP-FAC-0033</td><td>RF-FAC-033; RN-FAC-047; M05 §5.3; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Resolver el punto de venta con un servicio puro (RN-FAC-047).</td><td>Dos servicios con puntos de venta propios distintos en un mismo grupo generan la excepción &quot;2 o más servicios con puntos de venta diferentes&quot;.</td></tr><tr><td>CP-FAC-0034</td><td>RF-FAC-034; RN-FAC-045; M05 §5.3; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Validar cada candidato con las reglas del comprobante individual (RN-FAC-045).</td><td>Un candidato con cantidad 0 en un renglón genera excepción.</td></tr></tbody></table><h3 id="_1-4-bandeja-de-excepciones-m05-§5-4" tabindex="-1">1.4 Bandeja de excepciones (M05 §5.4) <a class="header-anchor" href="#_1-4-bandeja-de-excepciones-m05-§5-4" aria-label="Permalink to &quot;1.4 Bandeja de excepciones (M05 §5.4)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0035</td><td>RF-FAC-035; M05 §5.4; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Ofrecer una bandeja de excepciones con caso, cliente, cuenta, servicio, contrato, período, problema o dato faltante, código de motivo, severidad, etapa, estado, responsable (rol y usuario), módulo dueño del dato, siguiente acción, fecha…</td><td>ITEM-099 aparece con &quot;Factura A sin CUIT · Bloqueado en prevalidación · Datos de clientes · Completar y validar situación fiscal&quot;.</td></tr><tr><td>CP-FAC-0036</td><td>RF-FAC-036; M05 §5.4; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Excepciones: 2 abiertas (ESC-02), 1 resuelta —</td><td>Mantener un catálogo de motivos tipificados con categoría, severidad, responsable y acción por defecto y enlace a la pantalla de corrección.</td><td>Cada excepción tiene un motivo del catálogo; no existen excepciones de texto libre sin código.</td></tr><tr><td>CP-FAC-0037</td><td>RF-FAC-037; M05 §5.4; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>integración</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Aislar errores individuales y continuar con los casos válidos; detectar fallos sistémicos (credencial fiscal inválida, integración caída, error de configuración que afecta más de <code>PRM-FAC-033</code> % del bloque) y <strong>pausar</strong> el lote en lugar de…</td><td>Con la credencial ARCA vencida el lote queda &quot;pausado: credencial fiscal inválida&quot; y los casos siguen &quot;aprobados&quot; sin excepción individual.</td></tr><tr><td>CP-FAC-0038</td><td>RF-FAC-038; M05 §5.4; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Excepciones: 2 abiertas (ESC-02), 1 resuelta —</td><td>Asignar y derivar excepciones al responsable o al módulo dueño (M01 datos fiscales, M03 lecturas, M04 tarifa, M06 fiscal, M02 contrato), con notificación y plazo.</td><td>El supervisor de consumos recibe la excepción ITEM-100 en su bandeja con enlace a la lectura.</td></tr><tr><td>CP-FAC-0039</td><td>RF-FAC-039; M05 §5.4; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Reprocesar solo los casos pendientes en una ejecución vinculada al lote original, verificando antes la emisión previa de cada caso.</td><td>Tras corregir 2 casos, la reemisión genera 2 comprobantes y 0 duplicados.</td></tr><tr><td>CP-FAC-0040</td><td>RF-FAC-040; M05 §5.4; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Acta: Acta de AG-C1 10/2026 aprobada (v1) —</td><td>Excluir un caso con causa (no facturar en este período) con aprobación, o trasladarlo al próximo ciclo; ambos quedan en el acta.</td><td>Un caso excluido figura en el acta con causa, aprobador y fecha.</td></tr><tr><td>CP-FAC-0041</td><td>RF-FAC-041; M05 §5.4; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Distinguir y contar por separado: prevalidación bloqueada, rechazo fiscal, emitido con observaciones, incierto, excluido con motivo, pendiente; nunca ocultarlos bajo un &quot;lote completado&quot;.</td><td>El resumen del lote muestra las seis cifras y su suma coincide con el universo.</td></tr><tr><td>CP-FAC-0042</td><td>RF-FAC-042; M05 §5.4; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Conservar la relación entre caso original, corrección, ejecución nueva y comprobantes emitidos.</td><td>Desde ITEM-099 se navega a la corrección del CUIT, al reproceso y al comprobante emitido.</td></tr></tbody></table><h3 id="_1-5-aprobacion-m05-§5-5" tabindex="-1">1.5 Aprobación (M05 §5.5) <a class="header-anchor" href="#_1-5-aprobacion-m05-§5-5" aria-label="Permalink to &quot;1.5 Aprobación (M05 §5.5)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0043</td><td>RF-FAC-043; M05 §5.5; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Excepciones: 2 abiertas (ESC-02), 1 resuelta —</td><td>Aprobar la emisión según rol con un resumen obligatorio: universo, aptos, excepciones por motivo, totales por servicio y concepto, variaciones, muestra revisada y advertencias; workflow T11 por umbral de importe total (<code>PRM-FAC-072</code>).</td><td>Un lote por encima del umbral requiere dos aprobaciones; sin ellas el botón Emitir no está disponible.</td></tr><tr><td>CP-FAC-0044</td><td>RF-FAC-044; M05 §5.5; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Excepciones: 2 abiertas (ESC-02), 1 resuelta —</td><td>Permitir la aprobación parcial: se aprueban los aptos y las excepciones siguen pendientes de corrección.</td><td>Se aprueban 98 de 100 casos; los 2 restantes siguen en la bandeja.</td></tr><tr><td>CP-FAC-0045</td><td>RF-FAC-045; M05 §5.5; PRO-O4-09</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Invalidar la aprobación de los casos afectados si cambia una versión congelada (por ejemplo, se corrige una lectura) y exigir re-prefacturarlos y re-aprobarlos; los ya emitidos no se tocan.</td><td>Corregir la lectura de un caso aprobado lo devuelve a &quot;prefacturado&quot; con la diferencia explicada.</td></tr><tr><td>CP-FAC-0046</td><td>RF-FAC-046; M05 §5.5; PRO-O4-09</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Exigir que la muestra de control haya sido marcada como revisada antes de aprobar lotes con más de <code>PRM-FAC-034</code> casos.</td><td>Un lote de 5.000 casos sin muestra revisada no se puede aprobar.</td></tr><tr><td>CP-FAC-0174</td><td>RF-FAC-174; RN-FAC-154; M05 §5.5; PRO-O7-07</td><td>O7</td><td>Estándar</td><td>integración</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td><strong>Cola de revisión previa</strong> antes de autorizar: los casos cuyas cuentas pertenecen a las categorías o condiciones especiales configuradas (PRM-FAC-161: grandes usuarios / categorías tarifarias de demanda, usuario-generador, contratos con…</td><td>Un gran usuario de la categoría configurada queda en <code>reviewPending</code> con su detalle de demanda y comparación con el período anterior; el resto del lote se emite; sin aprobación de la revisión no recibe CAE.</td></tr></tbody></table><h3 id="_1-6-emision-y-numeracion-del-lote-m05-§5-6" tabindex="-1">1.6 Emisión y numeración del lote (M05 §5.6) <a class="header-anchor" href="#_1-6-emision-y-numeracion-del-lote-m05-§5-6" aria-label="Permalink to &quot;1.6 Emisión y numeración del lote (M05 §5.6)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0047</td><td>RF-FAC-047; M05 §5.6; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Emitir en un job de fondo por bloques de tamaño configurable (<code>PRM-FAC-035</code>), con progreso, métricas (casos por minuto, tiempo estimado, emitidos, errores) y acciones de pausar, reanudar y cancelar lo pendiente.</td><td>Pausar detiene después del bloque en curso; reanudar continúa desde el siguiente sin duplicar.</td></tr><tr><td>CP-FAC-0048</td><td>RF-FAC-048; M05 §5.6; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>integración</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Numerar estrictamente en forma correlativa por (tipo de numeración, punto de venta) en el <strong>orden de emisión</strong> del lote, dentro de la misma transacción que persiste los comprobantes y actualiza el numerador; sin huecos ni duplicados. El…</td><td>El número se asigna al emitir, en orden del lote, y si ARCA rechaza se reenvía el mismo número (DEC-035). Un fallo en el bloque 7 no consume números: el bloque 8 continúa desde el último número confirmado del bloque 6.</td></tr><tr><td>CP-FAC-0049</td><td>RF-FAC-049; M05 §5.6; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Ciclos: <code>AG-C1</code> agua (corte día 5), <code>AG-C2</code> agua (día 20), <code>ELE-C1</code> electricidad (día 10) <code>GAS-C1</code> gas (día 15, bimestral)</td><td>Ordenar la emisión por cuenta, alfabético, zona/sector/recorrido postal, ruta de reparto, o calle y número, porque el orden define la numeración y el reparto.</td><td>Con orden por ruta, los números crecen en la secuencia de la planilla de reparto.</td></tr><tr><td>CP-FAC-0050</td><td>RF-FAC-050; M05 §5.6; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Registrar por lote el rango de numeración emitido por tipo y punto de venta (desde, hasta, tipo de autorización).</td><td>El lote muestra &quot;Factura B 0002: 00001001–00001098, CAE&quot;.</td></tr><tr><td>CP-FAC-0051</td><td>RF-FAC-051; M05 §5.6; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>integración</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Al emitir cada caso: crear el comprobante inmutable con su detalle, registrar <code>billedPeriods</code>, consumir ítems facturables y cuotas, publicar <code>fac.invoice.issued</code> con una obligación por servicio para M07, solicitar autorización a M06 si el…</td><td>Cada comprobante emitido tiene su evento en el outbox en la misma transacción.</td></tr><tr><td>CP-FAC-0052</td><td>RF-FAC-052; M05 §5.6; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>integración</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Garantizar idempotencia con una clave de operación por caso (tenant, lote, caso, versión del universo); reintentar nunca duplica comprobantes ni consumos.</td><td>Matar el worker en mitad del bloque y relanzar produce el mismo conjunto de comprobantes.</td></tr><tr><td>CP-FAC-0053</td><td>RF-FAC-053; M05 §5.6; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Reanudar procesos interrumpidos desde el último bloque confirmado, mostrando qué quedó emitido y qué pendiente.</td><td>El lote reanudado informa &quot;bloques confirmados 1–6, en curso 7&quot;.</td></tr><tr><td>CP-FAC-0054</td><td>RF-FAC-054; M05 §5.6; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Conservar en cada comprobante el tenant, titular, asociado, cuenta, servicio(s), contrato(s), lote, versión del universo y referencia al resultado de cálculo.</td><td>Desde FAC-DEMO-001 se llega al cálculo ARS 3.000 + 20 × ARS 500.</td></tr><tr><td>CP-FAC-0055</td><td>RF-FAC-055; M05 §5.6; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>integración</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Ofrecer el <strong>servicio de emisión individual</strong> (fuera de lote) para refacturación, factura manual, altas y bajas, venta de prepaga, ventas (M11), intereses (M08) e inmediata/in situ, con las mismas validaciones, numeración e idempotencia.</td><td>M08 emite una ND de intereses a través del servicio y obtiene número, PDF y estado fiscal.</td></tr><tr><td>CP-FAC-0056</td><td>RF-FAC-056; M05 §5.6; PRO-O10-13</td><td>O10</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Registrar al cierre del lote, si <code>PRM-FAC-061</code> lo indica, el evento para capitalizar sobre lo facturado (M17).</td><td>El capital se factura como renglón identificado en la factura del servicio, con auxiliar separado y leyenda (DEC-061); el mínimo de capital entra en O5 (DEC-019). Con el parámetro activo, M17 recibe <code>fac.billingRun.closed</code> con totales por rubro de capital.</td></tr></tbody></table><h3 id="_1-7-estado-fiscal-y-autorizacion-dependencia-de-m06-m05-§5-7" tabindex="-1">1.7 Estado fiscal y autorización (dependencia de M06) (M05 §5.7) <a class="header-anchor" href="#_1-7-estado-fiscal-y-autorizacion-dependencia-de-m06-m05-§5-7" aria-label="Permalink to &quot;1.7 Estado fiscal y autorización (dependencia de M06) (M05 §5.7)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0057</td><td>RF-FAC-057; M05 §5.7; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Mantener el <strong>estado fiscal</strong> de cada comprobante separado del bloqueo de cobro y del estado comercial.</td><td>Un comprobante puede estar &quot;autorizado&quot; y &quot;bloqueado para cobro&quot; a la vez sin ambigüedad.</td></tr><tr><td>CP-FAC-0058</td><td>RF-FAC-058; M05 §5.7; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Encolar la autorización en M06 y consumir su resultado; ofrecer un tablero de pendientes por lote, punto de venta y antigüedad que reemplaza la alerta manual &quot;Hay facturas electrónicas pendientes de autorizar&quot;.</td><td>El tablero muestra pendientes con más de 1 día en rojo; la alerta al iniciar sesión deja de ser necesaria.</td></tr><tr><td>CP-FAC-0059</td><td>RF-FAC-059; M05 §5.7; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Ciclos: <code>AG-C1</code> agua (corte día 5), <code>AG-C2</code> agua (día 20), <code>ELE-C1</code> electricidad (día 10) <code>GAS-C1</code> gas (día 15, bimestral)</td><td>Ante respuesta incierta, pedir a M06 la consulta del comprobante o del último autorizado antes de reintentar; no reemitir ni renumerar a ciegas.</td><td>Un corte de red tras el envío deja el comprobante &quot;incierto&quot;; la conciliación lo resuelve como autorizado sin segunda solicitud.</td></tr><tr><td>CP-FAC-0060</td><td>RF-FAC-060; M05 §5.7; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Pausar el lote ante un problema fiscal global informado por M06 (credencial vencida, servicio no disponible, punto de venta inhabilitado).</td><td><code>fis.authorization.globalFailure</code> pausa todos los lotes del tenant en fase de autorización.</td></tr><tr><td>CP-FAC-0061</td><td>RF-FAC-061; M05 §5.7; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>integración</td><td>TEN-001 con Formatos de código: <code>GENERICO_40_43</code>, <code>PAGOFACIL_DEMO</code>, <code>SIRO_56_DEMO</code> con vectores de prueba <code>GENERICO_40_43</code></td><td>Reflejar rechazos y observaciones: un rechazo abre excepción &quot;rechazo fiscal&quot; con el código de ARCA; una observación se registra en el comprobante emitido y no habilita reemitir.</td><td>El resumen distingue &quot;emitidos con observación&quot;.</td></tr><tr><td>CP-FAC-0062</td><td>RF-FAC-062; M05 §5.7; PRO-O4-10</td><td>O4</td><td>Estándar</td><td>regla</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Marcar comprobantes emitidos bajo CAEA (contingencia o lotes grandes) y seguir su informe posterior que realiza M06.</td><td>El tablero muestra &quot;CAEA sin informar&quot; con su vencimiento.</td></tr><tr><td>CP-FAC-0063</td><td>RF-FAC-063; M05 §5.7; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Distribuir y publicar al socio solo comprobantes autorizados o que no requieren autorización.</td><td>Un comprobante pendiente de CAE no se envía por email.</td></tr></tbody></table><h3 id="_1-8-modalidad-separada-y-agrupada-grupos-de-facturacion-m05-§5-8" tabindex="-1">1.8 Modalidad separada y agrupada; grupos de facturación (M05 §5.8) <a class="header-anchor" href="#_1-8-modalidad-separada-y-agrupada-grupos-de-facturacion-m05-§5-8" aria-label="Permalink to &quot;1.8 Modalidad separada y agrupada; grupos de facturación (M05 §5.8)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0064</td><td>RF-FAC-064; M05 §5.8; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Configurar la modalidad por defecto del tenant (separada o agrupada) y excepciones por servicio, cuenta o titular, con vigencia desde un período.</td><td>Por defecto, separada por servicio; agrupada solo si se activa por grupo (DEC-034). Dos tenants con modalidades distintas no se afectan; el cambio rige desde un período sin alterar emitidos.</td></tr><tr><td>CP-FAC-0065</td><td>RF-FAC-065; M05 §5.8; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Modalidad separada: un comprobante por servicio y contrato que identifica el servicio; servicios distintos conservan documentos independientes.</td><td>Ana recibe FAC-AG-DEMO-002 (agua) y FAC-INT-DEMO-002 (internet).</td></tr><tr><td>CP-FAC-0066</td><td>RF-FAC-066; M05 §5.8; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Grupo de facturación con titular, servicios y contratos incluidos, domicilio postal y de reparto, punto de venta o talonario propio o general, periodicidad común, trama de vencimientos, canal de entrega, tipo de factura propio y opción…</td><td>El grupo se arma, modifica y desarma con vigencia y auditoría; desarmarlo no reabre períodos cerrados.</td></tr><tr><td>CP-FAC-0067</td><td>RF-FAC-067; M05 §5.8; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Bloquear al configurar un grupo las combinaciones inválidas: servicios de distintos titulares, CUIT/DNI o tenants; servicio que por norma, regulador o regla propia exige documento independiente; prestación de otra razón social…</td><td>Agregar un servicio marcado &quot;documento independiente&quot; al grupo falla con el motivo.</td></tr><tr><td>CP-FAC-0068</td><td>RF-FAC-068; M05 §5.8; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Registrar la validación fiscal de cada combinación (contador del tenant) antes de habilitar el grupo para emitir.</td><td>Un grupo sin validación fiscal registrada queda &quot;borrador&quot; y sus servicios se emiten separados.</td></tr><tr><td>CP-FAC-0069</td><td>RF-FAC-069; M05 §5.8; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>En cada comprobante agrupado, cada renglón identifica servicio, contrato o suministro, período, lecturas, conceptos y tributos propios, con subtotal por servicio.</td><td>Desde el comprobante se reconstruye el cálculo de cada servicio igual que si se hubiera emitido solo.</td></tr><tr><td>CP-FAC-0070</td><td>RF-FAC-070; M05 §5.8; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Publicar una obligación por servicio dentro del comprobante agrupado para que M07 aplique la regla de imputación del tenant.</td><td>La suma de las obligaciones por servicio es igual al total del comprobante.</td></tr><tr><td>CP-FAC-0071</td><td>RF-FAC-071; M05 §5.8; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Las NC, ND y anulaciones de un comprobante agrupado referencian el original e indican el servicio afectado; corregir un servicio no altera los renglones de los demás.</td><td>Una NC por internet en el comprobante de CU-103 no modifica energía ni la tasa.</td></tr><tr><td>CP-FAC-0072</td><td>RF-FAC-072; M05 §5.8; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Resolver servicios de periodicidad distinta dentro de un grupo con una regla configurable (emitir lo vencido en el próximo comprobante del grupo, emitir aparte o prorratear) e informar en el lote qué servicios quedaron fuera del grupo y…</td><td>El lote lista &quot;Sepelio (trimestral) fuera del grupo: no vence en este período&quot;.</td></tr><tr><td>CP-FAC-0073</td><td>RF-FAC-073; M05 §5.8; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Mostrar en las vistas del socio, la landing y las APIs el comprobante agrupado con apertura por servicio: cuánto corresponde y qué se pagó de cada uno (dato de pagos provisto por M07).</td><td>El socio ve energía ARS 28.000, internet ARS 15.000 y tasa ARS 1.200 por separado.</td></tr><tr><td>CP-FAC-0074</td><td>RF-FAC-074; M05 §5.8; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Cambiar la modalidad o el grupo no reemite ni fusiona comprobantes históricos; la regla de transición rige desde el período siguiente.</td><td>Pasar de separada a agrupada en diciembre no modifica las facturas de noviembre.</td></tr><tr><td>CP-FAC-0075</td><td>RF-FAC-075; M05 §5.8; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Ciclos: <code>AG-C1</code> agua (corte día 5), <code>AG-C2</code> agua (día 20), <code>ELE-C1</code> electricidad (día 10) <code>GAS-C1</code> gas (día 15, bimestral)</td><td>Facturar varios suministros o inmuebles del mismo servicio de un titular según la regla del tenant.</td><td>Un titular con dos medidores de agua recibe el resultado que indique la regla vigente, sin sumar consumos entre medidores.</td></tr><tr><td>CP-FAC-0076</td><td>RF-FAC-076; M05 §5.8; PRO-O5-07</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Proveer a M07 los datos del resumen de cuenta (comprobantes incluidos, importes y servicio) en ambas modalidades; el resumen no es un comprobante ni una deuda adicional.</td><td>El resumen RES-DEMO-001 muestra ARS 38.000 y no genera una tercera obligación.</td></tr></tbody></table><h3 id="_1-9-tipos-de-comprobante-letras-puntos-de-venta-y-numeracion-m05-§5-9" tabindex="-1">1.9 Tipos de comprobante, letras, puntos de venta y numeración (M05 §5.9) <a class="header-anchor" href="#_1-9-tipos-de-comprobante-letras-puntos-de-venta-y-numeracion-m05-§5-9" aria-label="Permalink to &quot;1.9 Tipos de comprobante, letras, puntos de venta y numeración (M05 §5.9)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0077</td><td>RF-FAC-077; M05 §5.9; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>integración</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Catálogo de tipos de comprobante: código interno, código ARCA, descripción y abreviatura, <strong>letra como campo explícito</strong> (A, B, C, M, E, sin letra), clase (factura, ND, NC, liquidación de servicios públicos, ticket, interno, CVLP, recibo…</td><td>La factura B, la ND B y la NC B existen con letra &quot;B&quot; y su par de reversión configurado.</td></tr><tr><td>CP-FAC-0078</td><td>RF-FAC-078; M05 §5.9; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Matriz de resolución por condición fiscal del receptor: comprobante por defecto de factura, ND y NC; factura y crédito de servicio público; versiones MiPyME (FCE) con umbral; ticket.</td><td>Para Consumidor Final la matriz resuelve Factura B, ND B, NC B y LSP B.</td></tr><tr><td>CP-FAC-0079</td><td>RF-FAC-079; M05 §5.9; PRO-O4-10</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Permitir un comprobante propio por servicio para débito y para crédito.</td><td>Un servicio con comprobante propio lo usa cuando todos los servicios del comprobante coinciden.</td></tr><tr><td>CP-FAC-0080</td><td>RF-FAC-080; M05 §5.9; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Puntos de venta con código, descripción, tipo (electrónico CAE, CAEA, CAI/preimpreso, manual, controlador fiscal, interno), sucursal, servicios y canales habilitados, domicilio, estado y vigencia; punto de venta 0 solo para comprobantes…</td><td>Un comprobante fiscal con punto de venta 0 es rechazado en validación.</td></tr><tr><td>CP-FAC-0081</td><td>RF-FAC-081; M05 §5.9; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Numeradores por (tipo de numeración, punto de venta) con último número, tipo de autorización (CAE, CAEA, CAI) y datos del CAI con vencimiento; se crean al habilitar la combinación por acción explícita, nunca implícitamente con un &quot;punto de…</td><td>Emitir con una combinación sin numerador produce excepción de configuración, no un numerador nuevo.</td></tr><tr><td>CP-FAC-0082</td><td>RF-FAC-082; M05 §5.9; PRO-O4-10</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Talonario propio por grupo de facturación o numeración general.</td><td>Un grupo con talonario propio numera independiente del general.</td></tr><tr><td>CP-FAC-0083</td><td>RF-FAC-083; M05 §5.9; PRO-O4-10</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Numeración manual forzada solo para un comprobante individual, con permiso <code>fac.numeracion.forzar</code>, habilitación <code>PRM-FAC-041</code> y verificación de que el número no exista.</td><td>Forzar un número ya existente devuelve error; en un lote no se permite.</td></tr><tr><td>CP-FAC-0084</td><td>RF-FAC-084; M05 §5.9; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Controlar correlatividad y huecos por numerador; reparar un numerador desfasado solo con propuesta, aprobación y auditoría (no auto-reparación silenciosa).</td><td>El reporte de correlatividad muestra 0 huecos tras emitir 10.000 comprobantes.</td></tr><tr><td>CP-FAC-0085</td><td>RF-FAC-085; M05 §5.9; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>integración</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Antes de habilitar un numerador electrónico o reanudar tras una incidencia, sincronizar con el último comprobante autorizado en ARCA (servicio de M06).</td><td>Si ARCA informa 1.100 y el numerador local 1.098, la emisión se bloquea hasta conciliar.</td></tr></tbody></table><h3 id="_1-10-vencimientos-y-tramas-m05-§5-10" tabindex="-1">1.10 Vencimientos y tramas (M05 §5.10) <a class="header-anchor" href="#_1-10-vencimientos-y-tramas-m05-§5-10" aria-label="Permalink to &quot;1.10 Vencimientos y tramas (M05 §5.10)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0086</td><td>RF-FAC-086; M05 §5.10; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Tramas: <code>TR-AG</code> 2 vencimientos, 3 % fijo; <code>TR-ELE</code> 3 vencimientos por rango de importe <code>TR-GAS</code> 2 vencimientos, % diario</td><td>Soportar de 1 a 4 vencimientos por comprobante, cada uno con fecha, importe total y recargo, más el próximo vencimiento impreso.</td><td>FAC-DEMO-001 muestra vencimientos 15/11, 25/11 y 05/12/2026 con sus importes.</td></tr><tr><td>CP-FAC-0087</td><td>RF-FAC-087; M05 §5.10; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Tramas: <code>TR-AG</code> 2 vencimientos, 3 % fijo; <code>TR-ELE</code> 3 vencimientos por rango de importe <code>TR-GAS</code> 2 vencimientos, % diario</td><td>Configurar tramas por servicio, ciclo y tipo de factura: cantidad de vencimientos, separación entre fechas y recargo de cada uno, con los modos fijo en pesos, porcentaje fijo capitalizado, porcentaje diario, trama por rango de importe y…</td><td>Con trama &quot;fijo en pesos&quot; de ARS 100: Vto2 = T + 100, Vto3 = T + 200, Vto4 = T + 300.</td></tr><tr><td>CP-FAC-0088</td><td>RF-FAC-088; RN-FAC-012, RN-FAC-015, RN-FAC-058; M05 §5.10; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Tramas: <code>TR-AG</code> 2 vencimientos, 3 % fijo; <code>TR-ELE</code> 3 vencimientos por rango de importe <code>TR-GAS</code> 2 vencimientos, % diario</td><td>Validar vencimientos con RN-FAC-012 a RN-FAC-015 y RN-FAC-058.</td><td>Un Vto3 a 75 días de Vto2 con total mayor a 60 días es rechazado.</td></tr><tr><td>CP-FAC-0089</td><td>RF-FAC-089; M05 §5.10; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Tramas: <code>TR-AG</code> 2 vencimientos, 3 % fijo; <code>TR-ELE</code> 3 vencimientos por rango de importe <code>TR-GAS</code> 2 vencimientos, % diario</td><td>Aplicar la regla de consistencia: si el total de un vencimiento posterior resulta menor que el total del primero, se igualan los posteriores al primero.</td><td>Un recargo negativo por error de trama no reduce el importe.</td></tr><tr><td>CP-FAC-0090</td><td>RF-FAC-090; M05 §5.10; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Formatos de código: <code>GENERICO_40_43</code>, <code>PAGOFACIL_DEMO</code>, <code>SIRO_56_DEMO</code> con vectores de prueba <code>GENERICO_40_43</code></td><td>Exhibir el importe correspondiente a cada vencimiento en el comprobante, en la app y en los códigos de pago.</td><td>El código de pago codifica los importes del 1.º y 2.º vencimiento iguales a los impresos.</td></tr><tr><td>CP-FAC-0091</td><td>RF-FAC-091; M05 §5.10; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>No precargar tasas ni montos de recargo productivos; la trama demo se identifica como demostración.</td><td>Un tenant nuevo no tiene trama activa hasta que la configura y aprueba.</td></tr><tr><td>CP-FAC-0092</td><td>RF-FAC-092; M05 §5.10; PRO-O4-11</td><td>O4</td><td>Estándar</td><td>regla</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>En comprobantes individuales, permitir emitir N comprobantes consecutivos sumando un mes al primer vencimiento de cada uno.</td><td>Emitir 3 cuotas manuales crea vencimientos en tres meses consecutivos.</td></tr></tbody></table><h3 id="_1-11-bloqueo-de-comprobantes-m05-§5-11" tabindex="-1">1.11 Bloqueo de comprobantes (M05 §5.11) <a class="header-anchor" href="#_1-11-bloqueo-de-comprobantes-m05-§5-11" aria-label="Permalink to &quot;1.11 Bloqueo de comprobantes (M05 §5.11)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0093</td><td>RF-FAC-093; M05 §5.11; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Ciclos: <code>AG-C1</code> agua (corte día 5), <code>AG-C2</code> agua (día 20), <code>ELE-C1</code> electricidad (día 10) <code>GAS-C1</code> gas (día 15, bimestral)</td><td>Mantener el catálogo de causas de bloqueo de cobro.</td><td>Una causa en uso no se puede eliminar, solo inactivar.</td></tr><tr><td>CP-FAC-0094</td><td>RF-FAC-094; M05 §5.11; PRO-O5-04</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Bloquear y desbloquear comprobantes impagos en forma individual y masiva con filtros (cuenta, titular, tipo, fecha de emisión, vencimiento), registrando historial con fecha, causa, usuario y motivo.</td><td>Desbloquear un comprobante deja una entrada de historial con causa nula.</td></tr><tr><td>CP-FAC-0095</td><td>RF-FAC-095; M05 §5.11; PRO-O6-01</td><td>O6</td><td>Estándar</td><td>integración</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Bloquear o desbloquear con cobro de intereses: en la misma operación se pide a M08 la emisión del comprobante de intereses (porcentaje y concepto configurables).</td><td>Desbloquear con intereses emite el comprobante de intereses y el desbloqueo en una única operación idempotente.</td></tr><tr><td>CP-FAC-0096</td><td>RF-FAC-096; M05 §5.11; PRO-O5-04</td><td>O5</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Propagar automáticamente, al emitir un lote, el bloqueo de cobro a los comprobantes nuevos de cuentas que ya tienen comprobantes bloqueados, con la causa de menor código.</td><td>Con la política activa, la factura nueva de una cuenta con bloqueo nace bloqueada.</td></tr><tr><td>CP-FAC-0097</td><td>RF-FAC-097; M05 §5.11; PRO-O5-04</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Publicar los cambios de bloqueo para que M07 impida el cobro en caja y canales.</td><td>Un comprobante bloqueado es rechazado en caja con la causa visible.</td></tr></tbody></table><h3 id="_1-12-anulacion-notas-de-credito-y-debito-reversion-m05-§5-12" tabindex="-1">1.12 Anulación, notas de crédito y débito, reversión (M05 §5.12) <a class="header-anchor" href="#_1-12-anulacion-notas-de-credito-y-debito-reversion-m05-§5-12" aria-label="Permalink to &quot;1.12 Anulación, notas de crédito y débito, reversión (M05 §5.12)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0098</td><td>RF-FAC-098; M05 §5.12; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Anular un comprobante <strong>no autorizado fiscalmente y sin pagos ni financiaciones</strong> con baja lógica (<code>commercialStatus = annulled</code>), motivo, aprobación y copia de auditoría; nunca se elimina físicamente.</td><td>El comprobante anulado sigue consultable con su contenido original y la marca de anulación.</td></tr><tr><td>CP-FAC-0099</td><td>RF-FAC-099; M05 §5.12; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>integración</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Revertir un comprobante autorizado o con pagos emitiendo una NC (o ND, si el original es crédito) asociada, con relación de anulación y marca para informar el comprobante asociado a ARCA.</td><td>La NC queda vinculada con <code>relationType = reversal</code> y <code>reportToTaxAuthority = true</code>.</td></tr><tr><td>CP-FAC-0100</td><td>RF-FAC-100; RN-FAC-073, RN-FAC-083; M05 §5.12; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Aplicar todas las validaciones de anulación y reversión (RN-FAC-073 a RN-FAC-083).</td><td>Una factura ya revertida no puede revertirse otra vez.</td></tr><tr><td>CP-FAC-0101</td><td>RF-FAC-101; M05 §5.12; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Liberar al anular o revertir lo que el comprobante consumió: consumos, cargos pendientes, cuotas, llamadas e internacionales, presupuestos, anticipos aplicados, franqueo, redondeo acumulado, registro de capital, conceptos de terceros…</td><td>Tras anular, el consumo vuelve a &quot;aprobado sin facturar&quot; y el período queda disponible.</td></tr><tr><td>CP-FAC-0102</td><td>RF-FAC-102; M05 §5.12; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Ofrecer opciones de reversión: revertir consumos (consumo espejo negativo), permitir volver a facturar (copia del consumo sin facturar), liberar créditos y débitos, revertir stock de productos (M13), fechas de vencimiento de la NC.</td><td>Con &quot;permitir volver a facturar&quot;, el próximo lote vuelve a tomar el consumo.</td></tr><tr><td>CP-FAC-0103</td><td>RF-FAC-103; M05 §5.12; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>integración</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Emitir <strong>créditos por comprobantes</strong> en masa por filtros o archivo importado, excluyendo los que tengan pagos (con lista de excluidos) y procesando en bloques idempotentes.</td><td>500 facturas seleccionadas con 3 pagadas generan 497 NC y la lista de 3 excluidas.</td></tr><tr><td>CP-FAC-0104</td><td>RF-FAC-104; M05 §5.12; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Tramas: <code>TR-AG</code> 2 vencimientos, 3 % fijo; <code>TR-ELE</code> 3 vencimientos por rango de importe <code>TR-GAS</code> 2 vencimientos, % diario</td><td>Emitir NC o ND parciales por servicio, renglón o importe, con causa y documentación; la diferencia de una corrección posterior a la emisión se simula y se emite como ND o NC por la diferencia, sin editar el original.</td><td>ESC-02: la corrección de ARS 12.000 a ARS 15.000 genera una ND de ARS 3.000 vinculada.</td></tr><tr><td>CP-FAC-0105</td><td>RF-FAC-105; M05 §5.12; PRO-O4-11</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Relacionar manualmente comprobantes de una misma cuenta de los últimos N días (no internos ni anulados), con las marcas &quot;anulación&quot; e &quot;informar CUIT&quot;.</td><td>Una NC manual queda vinculada a su factura y M06 la informa como asociada.</td></tr><tr><td>CP-FAC-0106</td><td>RF-FAC-106; M05 §5.12; PRO-O5-07</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Distinguir el crédito comercial de la devolución de dinero: la NC no implica reintegro; el reintegro lo gestiona M07 con su expediente.</td><td>Emitir una NC de ARS 2.000 no crea un pago saliente.</td></tr><tr><td>CP-FAC-0107</td><td>RF-FAC-107; M05 §5.12; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Anular comprobantes de venta (M11) con el mismo motor y reglas.</td><td>Una factura de venta de productos anulada libera su stock según la opción elegida.</td></tr></tbody></table><h3 id="_1-13-recategorizacion-retroactivos-y-modificacion-masiva-m05-§5-13" tabindex="-1">1.13 Recategorización, retroactivos y modificación masiva (M05 §5.13) <a class="header-anchor" href="#_1-13-recategorizacion-retroactivos-y-modificacion-masiva-m05-§5-13" aria-label="Permalink to &quot;1.13 Recategorización, retroactivos y modificación masiva (M05 §5.13)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0108</td><td>RF-FAC-108; M05 §5.13; PRO-O7-07</td><td>O7</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Recategorización masiva en tres familias de modo: energía por porcentaje de ahorro, energía por consumo total, gas por últimos 6/12 períodos (con consumo corregido opcional y proporcional a 365 días) y gas por cambio de cuadro (beneficio…</td><td>La simulación muestra categoría actual, propuesta y fundamento por servicio.</td></tr><tr><td>CP-FAC-0109</td><td>RF-FAC-109; M05 §5.13; PRO-O7-07</td><td>O7</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Filtros de recategorización: servicio, cuenta, grupo, zonas, categorías, solo prepagas, recategorización previa (nunca recategorizados o con menos de 6 períodos); vista previa, confirmación con aprobación, guarda la categoría anterior…</td><td>Tras confirmar, el contrato tiene la categoría nueva con vigencia y la nota &quot;Recategorizado por ahorro 22 %&quot;.</td></tr><tr><td>CP-FAC-0110</td><td>RF-FAC-110; M05 §5.13; PRO-O7-07</td><td>O7</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Ciclos: <code>AG-C1</code> agua (corte día 5), <code>AG-C2</code> agua (día 20), <code>ELE-C1</code> electricidad (día 10) <code>GAS-C1</code> gas (día 15, bimestral)</td><td>Corregir consumos de gas sin facturar con un factor base, excluyendo consumos divididos automáticamente (ejecuta M03 a pedido de la recategorización).</td><td>Los consumos corregidos quedan con su versión anterior consultable.</td></tr><tr><td>CP-FAC-0111</td><td>RF-FAC-111; M05 §5.13; PRO-O7-07</td><td>O7</td><td>Estándar</td><td>regla</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Retroactivos sobre consumos facturados (proceso 0) y sobre conceptos facturados (proceso 1), con cálculo por cantidad, tramo, importe fijo, porcentaje o proporcional por días, interés opcional con signo explícito, validaciones y control de…</td><td>Un retroactivo repetido con los mismos parámetros para la misma cuenta es rechazado.</td></tr><tr><td>CP-FAC-0112</td><td>RF-FAC-112; M05 §5.13; PRO-O4-11</td><td>O4</td><td>Estándar</td><td>regla</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Modificación masiva de comprobantes emitidos: todos los vencimientos, uno de ellos, fecha de emisión, próximo vencimiento o importes de los vencimientos 2 a 4, con filtros, vista previa, aprobación, exclusiones por cierre y auditoría por…</td><td>La auditoría de cada comprobante muestra valor anterior y nuevo.</td></tr><tr><td>CP-FAC-0113</td><td>RF-FAC-113; M05 §5.13; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Limitar la modificación masiva de comprobantes autorizados fiscalmente a datos no fiscales (vencimientos 2 a 4 e importes con recargo y próximo vencimiento).</td><td>Intentar cambiar la fecha de emisión de un autorizado lo excluye con motivo.</td></tr><tr><td>CP-FAC-0114</td><td>RF-FAC-114; M05 §5.13; PRO-O4-11</td><td>O4</td><td>Estándar</td><td>integración</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Cambiar la clasificación comercial (tipo de factura) de un comprobante sin afectar sus datos fiscales, con auditoría.</td><td>El cambio queda en historial y no reenvía nada a ARCA.</td></tr><tr><td>CP-FAC-0115</td><td>RF-FAC-115; M05 §5.13; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Tramas: <code>TR-AG</code> 2 vencimientos, 3 % fijo; <code>TR-ELE</code> 3 vencimientos por rango de importe <code>TR-GAS</code> 2 vencimientos, % diario</td><td>Proveer el motor genérico de operaciones masivas (borrador, vista previa, aprobación, aplicación por bloques, resultado por ítem) para que M11 implemente la modificación de cuotas pendientes (importe por porcentaje, costo del producto…</td><td>M11 ejecuta una operación &quot;desplazar vencimientos 1 mes&quot; con vista previa y resultado por cuota.</td></tr></tbody></table><h3 id="_1-14-facturacion-de-cuotas-y-de-terceros-items-facturables-m05-§5-14" tabindex="-1">1.14 Facturación de cuotas y de terceros; ítems facturables (M05 §5.14) <a class="header-anchor" href="#_1-14-facturacion-de-cuotas-y-de-terceros-items-facturables-m05-§5-14" aria-label="Permalink to &quot;1.14 Facturación de cuotas y de terceros; ítems facturables (M05 §5.14)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0116</td><td>RF-FAC-116; M05 §5.14; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Mantener la cola de <strong>ítems facturables</strong> (cargos manuales, retroactivos, importaciones de terceros, cuotas e intereses diferidos expuestos por M11/M08, cargos de técnica) con cuenta, contrato/servicio, concepto, cantidad, precio, período…</td><td>Un cargo pendiente sin período se toma en el primer lote del servicio y queda &quot;facturado&quot; con el id del comprobante.</td></tr><tr><td>CP-FAC-0117</td><td>RF-FAC-117; M05 §5.14; PRO-O4-11</td><td>O4</td><td>Estándar</td><td>regla</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Incluir cuotas en el lote por rango de vencimientos (hasta una fecha y no anteriores a 10 meses antes de la fecha desde) o por lista explícita, con intereses diferidos opcionales y filtro por tipo de cuota; agrupar cuotas asociadas a un…</td><td>Una cuota de la instalación financiada de internet sale en el bloque de internet.</td></tr><tr><td>CP-FAC-0118</td><td>RF-FAC-118; M05 §5.14; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Por defecto, las ventas y sus cuotas se facturan en documentos propios y se presentan juntas en el resumen; la inclusión en la factura del servicio solo se habilita para conceptos vinculados a ese servicio y con validación fiscal.</td><td>Una cuota de un electrodoméstico no puede asignarse al grupo de energía.</td></tr><tr><td>CP-FAC-0119</td><td>RF-FAC-119; M05 §5.14; PRO-O4-11</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>No emitir comprobantes que solo contengan cuotas cuando la cuenta no tiene ítems de servicio, si <code>PRM-FAC-062</code> está activo.</td><td>Con el parámetro activo, una cuenta con cuotas y sin servicios no genera comprobante en el lote.</td></tr><tr><td>CP-FAC-0120</td><td>RF-FAC-120; M05 §5.14; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Exhibir en un bloque separado los conceptos por cuenta y orden de terceros, solo si M06 confirma convenio vigente con fundamento; sin convenio el ítem es bloqueado como excepción.</td><td>Un ítem &quot;Tasa de bomberos&quot; sin convenio vigente genera la excepción &quot;Concepto de terceros sin convenio&quot;.</td></tr><tr><td>CP-FAC-0121</td><td>RF-FAC-121; M05 §5.14; PRO-O4-11</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Importaciones de terceros con formato canónico (cuenta o identificador, concepto, cantidad, precio, descripción, período) y adaptadores por origen: EMA (Excel), SAM (Excel + ancho fijo, variante Tasa Verde), EME (DBF de emergencias…</td><td>Un archivo IAL con un suministro inexistente se rechaza en la fila con &quot;CUENTA INEXISTENTE&quot;.</td></tr><tr><td>CP-FAC-0122</td><td>RF-FAC-122; M05 §5.14; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Las importaciones no consumen números de comprobante salvo al emitir efectivamente.</td><td>Importar sin emitir no altera ningún numerador.</td></tr><tr><td>CP-FAC-0123</td><td>RF-FAC-123; M05 §5.14; PRO-O7-07</td><td>O7</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Ciclos: <code>AG-C1</code> agua (corte día 5), <code>AG-C2</code> agua (día 20), <code>ELE-C1</code> electricidad (día 10) <code>GAS-C1</code> gas (día 15, bimestral)</td><td>Asociar datos de otro prestador para imprimir en el comprobante (por ejemplo, agua de otra empresa) por zona, sector y recorrido.</td><td>La factura de una cuenta del recorrido 12 imprime el bloque del otro prestador.</td></tr><tr><td>CP-FAC-0124</td><td>RF-FAC-124; M05 §5.14; PRO-O10-13</td><td>O10</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Facturar servicios de terceros revendidos de telefonía móvil (formato PR1: servicio, proporcional, cargo, abono, reintegro, consumo) informando líneas no encontradas, duplicadas y servicios activos no importados.</td><td>El reporte de importación lista líneas no encontradas.</td></tr><tr><td>CP-FAC-0125</td><td>RF-FAC-125; M05 §5.14; PRO-O10-13</td><td>O10</td><td>Estándar</td><td>regla</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Emitir CVLP (cuenta de venta y líquido producto) de servicios de terceros con comisiones (hasta tres), filtrable por período, fechas o número de lote, con ND opcional y exclusión opcional de percepciones.</td><td>Un CVLP con comisión de 5 % muestra bruto, comisión y líquido.</td></tr><tr><td>CP-FAC-0176</td><td>RF-FAC-176; RN-FAC-156; M05 §5.14; PRO-O10-13</td><td>O10</td><td>Estándar</td><td>regla</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Clases de ítem facturable &quot;depósito en garantía&quot;, &quot;aporte al fondo de subsidio&quot; y &quot;derecho de sepultura&quot; (adquisición y mantenimiento) en <code>billableItems.itemClass</code> y en los renglones, con bloque de impresión, clase fiscal de M06 y rol…</td><td>Un depósito de ARS 50.000 por préstamo ortopédico (ficticio) sale en el bloque &quot;Depósito en garantía (reintegrable)&quot; sin IVA ni percepciones y su obligación llega a M07 con <code>itemClass = guaranteeDeposit</code>; la cuota 3/24 del derecho de sepultura y el mantenimiento anual salen como renglones de clase <code>burialRightAcquisition</code> y <code>burialRightMaintenance</code> con el IVA que indique M06.</td></tr><tr><td>CP-FAC-0177</td><td>RF-FAC-177; RN-FAC-157; M05 §5.14; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Emitir por entidad jurídica (DEC-064, DEC-087): resolver <code>legalEntityId</code> por contrato o, si está vacío, por <code>tenantServices.legalEntityId</code> (M02), separar casos, comprobantes, talones y numeradores por entidad, y elegir punto de venta y…</td><td>Un titular con ELE de la entidad LE-01 e Internet de LE-02 en modalidad agrupada recibe dos comprobantes, uno por entidad, cada uno con su punto de venta y numeración; un talón nunca mezcla comprobantes de LE-01 y LE-02.</td></tr><tr><td>CP-FAC-0178</td><td>RF-FAC-178; RN-FAC-158; M05 §5.14; PRO-O7-07</td><td>O7</td><td>Estándar</td><td>regla</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Consumir <code>cat.contract.meteringRegimeChanged</code> (EVT-CAT-28) cuando afecta la facturación del período: volver a prefacturar los casos afectados de lotes preparados y registrar excepción si falta la lectura de retiro (RN-FAC-158).</td><td>Un cambio a <code>metered</code> con fecha efectiva 16/11/2026 sobre un lote AG de noviembre preparado marca el caso como afectado; al reprefacturar, el comprobante muestra cuota fija y consumo en dos renglones.</td></tr><tr><td>CP-FAC-0179</td><td>RF-FAC-179; RN-FAC-161; M05 §5.14; PRO-O4-10</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td><strong>Numeración de recibos de M07 por entidad jurídica</strong> (DEC-064, DEC-087; CTR-DAT-74): servicio interno <code>fac.service.nextNumber</code> que asigna el siguiente número de <code>numberSequences</code> para el tipo de recibo y el punto de venta de la entidad…</td><td>Dos cajas concurrentes de LE-01 y una de LE-02 obtienen números correlativos sin repetidos por entidad; un pedido con punto de venta de LE-01 y <code>legalEntityId</code> LE-02 se rechaza con <code>POS_CONFLICT</code> (RN-FAC-161).</td></tr></tbody></table><h3 id="_1-15-factura-manual-replicar-y-refacturacion-puntual-m05-§5-15" tabindex="-1">1.15 Factura manual, replicar y refacturación puntual (M05 §5.15) <a class="header-anchor" href="#_1-15-factura-manual-replicar-y-refacturacion-puntual-m05-§5-15" aria-label="Permalink to &quot;1.15 Factura manual, replicar y refacturación puntual (M05 §5.15)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0126</td><td>RF-FAC-126; M05 §5.15; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Editor de factura manual: cabecera (tipo de comprobante, punto de venta, número si es manual, letra, fecha, cuenta y domicilio, titular, vendedor, tipo de factura, depósito, período), deuda vencida del titular visible, opción &quot;registrar…</td><td>Un borrador puede guardarse incompleto; al emitir se valida y numera.</td></tr><tr><td>CP-FAC-0127</td><td>RF-FAC-127; RN-FAC-045, RN-FAC-058, RN-FAC-062; M05 §5.15; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Validar la factura manual con todas las reglas RN-FAC-045 y RN-FAC-058 a RN-FAC-062.</td><td>Un Vto1 a más de <code>PRM-FAC-050</code> días de hoy es rechazado.</td></tr><tr><td>CP-FAC-0128</td><td>RF-FAC-128; M05 §5.15; PRO-O4-11</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Replicar un comprobante como borrador nuevo copiando cabecera y renglones (todos los ítems si <code>PRM-FAC-051</code> lo permite), con fechas actuales.</td><td>El borrador replicado no comparte número ni estado con el original.</td></tr><tr><td>CP-FAC-0129</td><td>RF-FAC-129; M05 §5.15; PRO-O4-11</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Refacturar un servicio puntual sin reprocesar el lote: anula o revierte el original (según su estado), libera el período, recalcula con M04 y emite con secuencia nueva vinculada, en una operación auditada.</td><td>La refacturación de FAC-AG-DEMO-002 deja NC + nueva factura vinculadas y el lote original intacto.</td></tr><tr><td>CP-FAC-0130</td><td>RF-FAC-130; M05 §5.15; PRO-O5-07</td><td>O5</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Registrar el pago al emitir una factura de contado delegando el cobro a M07.</td><td>La factura contado queda emitida y cancelada en una misma operación.</td></tr><tr><td>CP-FAC-0131</td><td>RF-FAC-131; M05 §5.15; PRO-O4-11</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Al cargar un crédito manual, sugerir, obligar o ignorar la relación con el comprobante de origen según <code>PRM-FAC-052</code>.</td><td>Con &quot;obligar&quot;, una NC manual sin relación no se puede emitir.</td></tr><tr><td>CP-FAC-0132</td><td>RF-FAC-132; M05 §5.15; PRO-O4-11</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Universos: <code>GRUPO-CENTRO</code>, <code>GRUPO-NORTE</code>, <code>CONTROL</code> (10 cuentas) <code>GAS-TODOS</code></td><td>Marcar NC no automáticas (cargadas a mano) para su control.</td><td>El reporte de NC filtra &quot;no automáticas&quot;.</td></tr><tr><td>CP-FAC-0133</td><td>RF-FAC-133; M05 §5.15; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>migración</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Registrar comprobantes de administración pública con el formato que corresponda. <strong>[VERIFICAR]</strong> su contenido en ProCoop.</td><td>Se puede registrar el comprobante administrativo asociado a una factura y período.</td></tr></tbody></table><h3 id="_1-16-impresion-diseno-graficos-y-pdf-m05-§5-16" tabindex="-1">1.16 Impresión, diseño, gráficos y PDF (M05 §5.16) <a class="header-anchor" href="#_1-16-impresion-diseno-graficos-y-pdf-m05-§5-16" aria-label="Permalink to &quot;1.16 Impresión, diseño, gráficos y PDF (M05 §5.16)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0134</td><td>RF-FAC-134; M05 §5.16; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Plantillas de representación por tenant y reglas explícitas de selección por prioridad: forzada por el usuario, CVLP, clasificación comercial, servicio, prepaga, tipo de comprobante, condición fiscal, variantes electrónica / alternativa /…</td><td>Para cada comprobante la regla de selección devuelve exactamente una plantilla y la registra.</td></tr><tr><td>CP-FAC-0135</td><td>RF-FAC-135; M05 §5.16; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Formatos de código: <code>GENERICO_40_43</code>, <code>PAGOFACIL_DEMO</code>, <code>SIRO_56_DEMO</code> con vectores de prueba <code>GENERICO_40_43</code></td><td>Contenido de la representación: datos fiscales exigidos (definidos por M06), bloques por servicio con lecturas y consumos, <strong>gráfico de consumo</strong> de los últimos períodos agrupable por grupos de gráfico, historial, mensajes personalizados…</td><td>La factura de agua muestra el gráfico de 12 períodos y el bloque de terceros separado.</td></tr><tr><td>CP-FAC-0136</td><td>RF-FAC-136; M05 §5.16; PRO-O4-12</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Ciclos: <code>AG-C1</code> agua (corte día 5), <code>AG-C2</code> agua (día 20), <code>ELE-C1</code> electricidad (día 10) <code>GAS-C1</code> gas (día 15, bimestral)</td><td>Configurar el orden de impresión de los renglones (grupos con descripción, pie y orden).</td><td>Cambiar el orden altera la próxima representación, no las ya generadas.</td></tr><tr><td>CP-FAC-0137</td><td>RF-FAC-137; M05 §5.16; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>seguridad</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Generar el PDF por job con el QR fiscal, guardarlo en almacenamiento privado con huella SHA-256 y versión de plantilla, servirlo con URL firmada; contraseña opcional para impresión masiva; fuente y calidad de imagen parametrizables.</td><td>Regenerar el PDF de un comprobante reproduce el mismo contenido; la huella se conserva por versión.</td></tr><tr><td>CP-FAC-0138</td><td>RF-FAC-138; M05 §5.16; PRO-O4-12</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Ciclos: <code>AG-C1</code> agua (corte día 5), <code>AG-C2</code> agua (día 20), <code>ELE-C1</code> electricidad (día 10) <code>GAS-C1</code> gas (día 15, bimestral)</td><td>Reimprimir o generar duplicado con marca visible &quot;duplicado&quot;; cargo por reimpresión opcional (<code>PRM-FAC-053</code>).</td><td>La reimpresión queda auditada con usuario y motivo.</td></tr><tr><td>CP-FAC-0139</td><td>RF-FAC-139; M05 §5.16; PRO-O4-12</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Ciclos: <code>AG-C1</code> agua (corte día 5), <code>AG-C2</code> agua (día 20), <code>ELE-C1</code> electricidad (día 10) <code>GAS-C1</code> gas (día 15, bimestral)</td><td>Previsualizar plantillas en tamaño escritorio y celular con datos de demostración antes de publicarlas.</td><td>La publicación exige al menos una previsualización.</td></tr></tbody></table><h3 id="_1-17-codigo-de-barras-y-qr-m05-§5-17" tabindex="-1">1.17 Código de barras y QR (M05 §5.17) <a class="header-anchor" href="#_1-17-codigo-de-barras-y-qr-m05-§5-17" aria-label="Permalink to &quot;1.17 Código de barras y QR (M05 §5.17)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0140</td><td>RF-FAC-140; M05 §5.17; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Formatos de código: <code>GENERICO_40_43</code>, <code>PAGOFACIL_DEMO</code>, <code>SIRO_56_DEMO</code> con vectores de prueba <code>GENERICO_40_43</code></td><td>Motor <strong>declarativo</strong> de formatos: lista ordenada de segmentos (constante, convenio, código de empresa, prefijo de documento, identificador interno, tipo/punto de venta/número, importe de un vencimiento en centavos, recargo, días entre…</td><td>Un formato nuevo se da de alta sin programar y genera el código de una factura demo con el largo esperado.</td></tr><tr><td>CP-FAC-0141</td><td>RF-FAC-141; M05 §5.17; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Formatos de código: <code>GENERICO_40_43</code>, <code>PAGOFACIL_DEMO</code>, <code>SIRO_56_DEMO</code> con vectores de prueba <code>GENERICO_40_43</code></td><td>Biblioteca de dígitos verificadores: DV1 (ponderadores 1-3-5-7-9, suma/2 módulo 10, aplicable dos veces), DV2 (9-7-1-3, complemento a 10), DV3 (módulo 10 peso 3 en pares), DV4 (módulo 11 pesos decrecientes), DV5 (peso 3 en impares, sin…</td><td>Pruebas unitarias con vectores conocidos para cada algoritmo.</td></tr><tr><td>CP-FAC-0142</td><td>RF-FAC-142; M05 §5.17; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>migración</td><td>TEN-001 con Formatos de código: <code>GENERICO_40_43</code>, <code>PAGOFACIL_DEMO</code>, <code>SIRO_56_DEMO</code> con vectores de prueba <code>GENERICO_40_43</code></td><td>Precargar como plantillas de plataforma los formatos genéricos documentados: Pago Fácil 42, 46, 46_2, 50 y 50_2; Banco de Córdoba 43, 48, 50, 50_2 y 56; Banco Nación 38; Mutual Independiente 50; Credicoop 47 (solo lectura); AFIP 40…</td><td>Cada plantilla reproduce el código de ProCoop para la misma factura de prueba.</td></tr><tr><td>CP-FAC-0143</td><td>RF-FAC-143; M05 §5.17; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>migración</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Codificar facturas, notificaciones de deuda (M08), documentos de pago y solicitudes de pasarela, con los prefijos de documento 40 (notificación), 41 (factura), 42 (talón) y 43 (solicitud de pasarela) para compatibilidad con lo impreso…</td><td>Un código migrado con prefijo 41 se decodifica al comprobante correcto.</td></tr><tr><td>CP-FAC-0144</td><td>RF-FAC-144; M05 §5.17; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>integración</td><td>TEN-001 con Formatos de código: <code>GENERICO_40_43</code>, <code>PAGOFACIL_DEMO</code>, <code>SIRO_56_DEMO</code> con vectores de prueba <code>GENERICO_40_43</code></td><td>Validar el largo: si un importe o una cantidad de días excede el ancho del segmento, no truncar; registrar excepción de impresión y aplicar el formato alternativo configurado (por ejemplo SIRO 59 cuando el importe supera ARS 99.999,99 en…</td><td>Una factura de ARS 150.000 con SIRO 56 usa el formato extendido o queda en excepción, nunca un código inválido.</td></tr><tr><td>CP-FAC-0145</td><td>RF-FAC-145; M05 §5.17; PRO-O5-04</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Formatos de código: <code>GENERICO_40_43</code>, <code>PAGOFACIL_DEMO</code>, <code>SIRO_56_DEMO</code> con vectores de prueba <code>GENERICO_40_43</code></td><td>Servicio de decodificación para caja y rendiciones (M07): valida largo y DV, identifica documento y vencimiento, y admite modos heredados configurables para códigos migrados (número + sucursal, cuenta + importe).</td><td>Un código con DV incorrecto devuelve &quot;código de barras inválido&quot;.</td></tr><tr><td>CP-FAC-0146</td><td>RF-FAC-146; M05 §5.17; PRO-O5-06</td><td>O5</td><td>Estándar</td><td>integración</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Generar QR EMVCo de billeteras y pasarelas (Pagos360, SIRO, NaranjaX, Pronto Pago, ProvinciaNet, Helipagos) con datos del comercio y CRC16, solo si no hay débito automático y el vencimiento no pasó; generar links de pago en la impresión…</td><td>El QR de una factura vencida no se imprime.</td></tr><tr><td>CP-FAC-0147</td><td>RF-FAC-147; M05 §5.17; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>integración</td><td>TEN-001 con Formatos de código: <code>GENERICO_40_43</code>, <code>PAGOFACIL_DEMO</code>, <code>SIRO_56_DEMO</code> con vectores de prueba <code>GENERICO_40_43</code></td><td>Asignar formatos por tenant y por recaudador o canal, con convenio por formato y por tipo de documento (resuelve el conflicto de convenio de 10 y 11 caracteres de SIRO para factura y talón).</td><td>Factura y talón de LAG salen con su convenio correcto.</td></tr><tr><td>CP-FAC-0148</td><td>RF-FAC-148; M05 §5.17; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>migración</td><td>TEN-001 con Formatos de código: <code>GENERICO_40_43</code>, <code>PAGOFACIL_DEMO</code>, <code>SIRO_56_DEMO</code> con vectores de prueba <code>GENERICO_40_43</code></td><td>Probador de formatos: generar el código de un comprobante, decodificar un código y comparar con el generado por ProCoop durante el paralelo.</td><td>El probador marca diferencias carácter a carácter.</td></tr></tbody></table><h3 id="_1-18-talones-y-documentos-de-pago-m05-§5-18" tabindex="-1">1.18 Talones y documentos de pago (M05 §5.18) <a class="header-anchor" href="#_1-18-talones-y-documentos-de-pago-m05-§5-18" aria-label="Permalink to &quot;1.18 Talones y documentos de pago (M05 §5.18)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0149</td><td>RF-FAC-149; M05 §5.18; PRO-O4-12</td><td>O4</td><td>Estándar</td><td>regla</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Generar documentos de pago (talones) agrupando comprobantes de la misma cuenta y grupo de talón: suma de los 4 importes (los créditos restan), vencimientos del primer comprobante del grupo, número propio, historial de versiones.</td><td>Energía + agua + sepelio de una cuenta salen en un talón con un solo código.</td></tr><tr><td>CP-FAC-0150</td><td>RF-FAC-150; M05 §5.18; PRO-O4-12</td><td>O4</td><td>Estándar</td><td>regla</td><td>TEN-001 con Tramas: <code>TR-AG</code> 2 vencimientos, 3 % fijo; <code>TR-ELE</code> 3 vencimientos por rango de importe <code>TR-GAS</code> 2 vencimientos, % diario</td><td>Partir un comprobante en N talones-cuota con vencimientos propios; la última cuota absorbe el redondeo.</td><td>ARS 10.000 en 3 cuotas: 3.333,33 + 3.333,33 + 3.333,34.</td></tr><tr><td>CP-FAC-0151</td><td>RF-FAC-151; M05 §5.18; PRO-O5-07</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Cupón de pago único para la modalidad separada: un documento de pago que cancela varias facturas del resumen con la regla de imputación de M07. El cupón lo emite M07 (<code>paymentCoupons</code>, CTR-DAT-39); M05 aporta los comprobantes y sus códigos…</td><td>Pagar el cupón de ARS 38.000 cancela agua e internet.</td></tr><tr><td>CP-FAC-0152</td><td>RF-FAC-152; M05 §5.18; PRO-O5-07</td><td>O5</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Consultar documentos de pago con sus pagos y eliminar uno no pagado si <code>PRM-FAC-054</code> lo permite.</td><td>Un talón con pagos no se puede eliminar.</td></tr><tr><td>CP-FAC-0153</td><td>RF-FAC-153; M05 §5.18; PRO-O4-12</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Imprimir la factura simple si el talón tiene un solo comprobante (<code>PRM-FAC-055</code>).</td><td>Un talón de una sola factura no genera página de talón adicional.</td></tr></tbody></table><h3 id="_1-19-distribucion-impresion-y-reparto-email-whatsapp-portal-m05-§5-19" tabindex="-1">1.19 Distribución: impresión y reparto, email, WhatsApp, portal (M05 §5.19) <a class="header-anchor" href="#_1-19-distribucion-impresion-y-reparto-email-whatsapp-portal-m05-§5-19" aria-label="Permalink to &quot;1.19 Distribución: impresión y reparto, email, WhatsApp, portal (M05 §5.19)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0154</td><td>RF-FAC-154; M05 §5.19; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Registrar preferencias de entrega por titular, cuenta o grupo: papel, email, WhatsApp, app/portal (combinables), destinatarios, adhesión a factura digital con fecha y origen.</td><td>Ana elige email + app; su comprobante no entra en la impresión de papel.</td></tr><tr><td>CP-FAC-0155</td><td>RF-FAC-155; M05 §5.19; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Crear lotes de distribución por lote de emisión o selección manual, por canal, con agrupación del envío por cuenta, por socio o por socio y teléfono, y envío en tandas configurables.</td><td>Con agrupación por socio, Ana recibe un email con sus dos facturas.</td></tr><tr><td>CP-FAC-0156</td><td>RF-FAC-156; M05 §5.19; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Distribución: 60 % email, 25 % papel por 3 rutas, 15 % WhatsApp; 2 rebotes 100 % email</td><td>Enviar por email con PDF adjunto o link firmado y por WhatsApp con plantilla oficial del tenant, a través del centro de comunicaciones (T09), con plantilla configurable.</td><td>El aviso de factura emitida usa la plantilla <code>fac.invoice.issued</code> del tenant.</td></tr><tr><td>CP-FAC-0157</td><td>RF-FAC-157; M05 §5.19; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Publicar el comprobante en el portal y la app al quedar autorizado y notificar por push si el socio lo eligió.</td><td>El comprobante aparece en &quot;Mis facturas&quot; al recibir <code>fis.invoice.authorized</code>.</td></tr><tr><td>CP-FAC-0158</td><td>RF-FAC-158; M05 §5.19; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>integración</td><td>TEN-001 con Distribución: 60 % email, 25 % papel por 3 rutas, 15 % WhatsApp; 2 rebotes 100 % email</td><td>Registrar el resultado de cada envío (pendiente, enviado, entregado, leído, fallido, rebotado, devuelto en papel), con id del proveedor, clave de idempotencia y reintentos; ante rebote definitivo, derivar a papel según política.</td><td>Un email rebotado dos veces genera la pieza en el próximo lote de impresión.</td></tr><tr><td>CP-FAC-0159</td><td>RF-FAC-159; M05 §5.19; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Impresión masiva en lote o exportación a imprenta (PDF unificado ordenado y archivo de datos), mensajes personalizados por segmento, imagen intercalada, numeración de piezas postales por zona/sector/recorrido y orden con sub-orden &quot;i/n&quot;…</td><td>El PDF de imprenta respeta el orden de la ruta y cada sobre indica &quot;1/2&quot;, &quot;2/2&quot;.</td></tr><tr><td>CP-FAC-0160</td><td>RF-FAC-160; M05 §5.19; PRO-O4-12</td><td>O4</td><td>Estándar</td><td>integración</td><td>TEN-001 con Distribución: 60 % email, 25 % papel por 3 rutas, 15 % WhatsApp; 2 rebotes 100 % email</td><td>Rutas y repartidores de distribución con secuencia; planilla de reparto; registro de entrega o devolución por el repartidor desde la PWA de empleado (funciona sin conexión).</td><td>El repartidor marca &quot;devuelto: domicilio inexistente&quot; sin conexión y se sincroniza después.</td></tr><tr><td>CP-FAC-0161</td><td>RF-FAC-161; M05 §5.19; PRO-O4-12</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Empresas postales con importe y franqueo según cantidad de hojas por destinatario y zona; no cobrar franqueo a quien adhirió a factura digital con email válido.</td><td>Un socio adherido a email no tiene renglón de franqueo.</td></tr><tr><td>CP-FAC-0162</td><td>RF-FAC-162; M05 §5.19; PRO-O4-12</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Excluir servicios dados de baja al ordenar por zona/sector/recorrido del servicio y separar facturas por titular según cantidad.</td><td>Un servicio de baja no altera el orden de reparto.</td></tr><tr><td>CP-FAC-0163</td><td>RF-FAC-163; M05 §5.19; PRO-O4-12</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Consulta pública del comprobante sin login (landing) con datos mínimos de identificación, si el tenant la habilita.</td><td>La consulta sin login muestra solo comprobantes de la cuenta indicada con control anti-enumeración.</td></tr></tbody></table><h3 id="_1-20-cierre-de-ciclo-cierre-de-modulo-socio-y-transversales-m05-§5-20" tabindex="-1">1.20 Cierre de ciclo, cierre de módulo, socio y transversales (M05 §5.20) <a class="header-anchor" href="#_1-20-cierre-de-ciclo-cierre-de-modulo-socio-y-transversales-m05-§5-20" aria-label="Permalink to &quot;1.20 Cierre de ciclo, cierre de módulo, socio y transversales (M05 §5.20)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-FAC-0164</td><td>RF-FAC-164; M05 §5.20; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Excepciones: 2 abiertas (ESC-02), 1 resuelta —</td><td>Cerrar el ciclo con un <strong>acta</strong>: cuadre del universo (seleccionados = emitidos + emitidos con observación + pendientes + excluidos con causa + inciertos + rechazados), totales por servicio y concepto, estado de autorización y distribución…</td><td>Un lote de 100 con 98 emitidos y 2 pendientes puede cerrarse con el acta que muestra 2 trasladados; el período no aparenta 100 facturados.</td></tr><tr><td>CP-FAC-0165</td><td>RF-FAC-165; M05 §5.20; PRO-O4-12</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Reabrir un cierre con motivo y aprobación; la reapertura no modifica comprobantes autorizados ni reabre períodos de grupos desarmados.</td><td>Reabrir crea una versión nueva del acta y conserva la anterior.</td></tr><tr><td>CP-FAC-0166</td><td>RF-FAC-166; M05 §5.20; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Mantener la fecha de cierre del módulo de facturación y de ventas que impide emitir, modificar o anular con fecha anterior.</td><td>Una NC con fecha anterior al cierre es rechazada.</td></tr><tr><td>CP-FAC-0167</td><td>RF-FAC-167; M05 §5.20; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</td><td>Notificar resultados de cada fase del lote y auditar el lote y cada caso.</td><td>La auditoría del caso muestra cada transición con actor y hora.</td></tr><tr><td>CP-FAC-0168</td><td>RF-FAC-168; M05 §5.20; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>PWA del socio: lista de comprobantes de sus cuentas autorizadas con apertura por servicio, estado de pago (de M07), vencimiento e importe vigente según la fecha, descarga del PDF y acceso a pagar (M07).</td><td>Un socio no ve comprobantes de otra cuenta aunque comparta domicilio.</td></tr><tr><td>CP-FAC-0169</td><td>RF-FAC-169; M05 §5.20; PRO-O11-03</td><td>O11</td><td>Estándar</td><td>seguridad</td><td>TEN-001 con Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante…</td><td>Exponer API de consulta de comprobantes y códigos de pago para terceros y BI con token (T10).</td><td>Un token de un tenant no puede leer comprobantes de otro.</td></tr><tr><td>CP-FAC-0170</td><td>RF-FAC-170; M05 §5.20; PRO-O7-07</td><td>O7</td><td>Estándar</td><td>integración</td><td>TEN-001 con Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</td><td>Facturación in situ: emitir en el momento de la lectura cuando el régimen y la cooperativa lo permiten, con el servicio de emisión individual desde la app de lecturas (offline con reserva de rango de numeración).</td><td>Un lecturista emite sin conexión dentro del rango reservado y el sistema concilia al sincronizar.</td></tr><tr><td>CP-FAC-0171</td><td>RF-FAC-171; M05 §5.20; PRO-O7-07</td><td>O7</td><td>Estándar</td><td>regla</td><td>TEN-001 con Puntos de venta: 0002 electrónico CAE (lotes), 0003 electrónico (mostrador), 0000 interno 0005 electrónico CAE</td><td>Emitir la factura de venta de prepaga desde M03/M07 exigiendo que el total coincida con el simulado; si no coincide, revertir el consumo registrado. Redondeo, recargo o bonificación por forma de pago y opción de ND separada según…</td><td>Una diferencia de un centavo con el simulado aborta la venta sin dejar consumo huérfano.</td></tr><tr><td>CP-FAC-0172</td><td>RF-FAC-172; M05 §5.20; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</td><td>Todas las etiquetas por clave de diccionario y todos los datos aislados por tenant.</td><td>Cambiar <code>dict:fac.invoice</code> a &quot;Liquidación&quot; se refleja en todas las pantallas del tenant.</td></tr><tr><td>CP-FAC-0173</td><td>RF-FAC-173; M05 §5.20; PRO-O4-12</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Ciclos: <code>AG-C1</code> agua (corte día 5), <code>AG-C2</code> agua (día 20), <code>ELE-C1</code> electricidad (día 10) <code>GAS-C1</code> gas (día 15, bimestral)</td><td>Proveer los reportes y exportaciones de la sección 15.</td><td>Cada reporte declara universo y fecha de corte.</td></tr></tbody></table><h2 id="_2-casos-por-escenario-y-criterio-de-aceptacion-con-id" tabindex="-1">2. Casos por escenario y criterio de aceptación con ID <a class="header-anchor" href="#_2-casos-por-escenario-y-criterio-de-aceptacion-con-id" aria-label="Permalink to &quot;2. Casos por escenario y criterio de aceptación con ID&quot;">​</a></h2><p><strong>CP-FAC-5001 — ESC-02. (lote con excepciones) se prefactura</strong></p><ul><li>Cubre: ESC-02; M05 §17</li><li>Ola: O4 · Prioridad: Núcleo · Tipo: regla</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</li><li>Dado <code>LOTE-AG-DEMO-001</code> con 100 casos</li><li>Cuando se prefactura</li><li>Entonces 98 quedan aptos y <code>ITEM-099</code> (Factura A sin CUIT) y <code>ITEM-100</code> (lectura inconsistente) quedan en la bandeja con responsable y próxima acción; al emitir, el lote queda <code>issuedWithPending</code> con 98 emitidos y el reporte de cuadre muestra 100 = 98 + 2.</li></ul><p><strong>CP-FAC-5002 — ESC-04. (cliente con varios servicios) separada se emite</strong></p><ul><li>Cubre: ESC-04; relacionados: CU-103; M05 §17</li><li>Ola: O5 · Prioridad: Núcleo · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante agrupado CU-103 ARS 44.200 con pago demo de ARS 30.000 (en M07) 5 facturas…</li><li>Dado el titular del CU-103 con energía (ARS 28.000), internet (ARS 15.000) y tasa (ARS 1.200) en modalidad agrupada</li><li>Cuando se emite</li><li>Entonces hay un comprobante <code>RES-DEMO-001</code>-equivalente de ARS 44.200 con tres bloques y tres obligaciones; un pago de ARS 30.000 lo imputa M07 por obligación sin que FAC cambie el comprobante. con modalidad separada, el mismo titular recibe tres comprobantes y ningún renglón de un servicio aparece en el comprobante de otro.</li></ul><p><strong>CP-FAC-5003 — ESC-05. (cambio de universo) se agrega una cuenta y se excluye otra</strong></p><ul><li>Cubre: ESC-05; RF-FAC-179; RN-FAC-156, RN-FAC-157, RN-FAC-158; M05 §17</li><li>Ola: O4 · Prioridad: Núcleo · Tipo: seguridad</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001 y TEN-002; semillas de M05 §18.</li><li>Datos de prueba: Formatos de código: <code>GENERICO_40_43</code>, <code>PAGOFACIL_DEMO</code>, <code>SIRO_56_DEMO</code> con vectores de prueba <code>GENERICO_40_43</code></li><li>Dado un lote preparado (v1, 100 casos)</li><li>Cuando se agrega una cuenta y se excluye otra</li><li>Entonces se congela v2, la diferencia muestra +1/−1 y solo esos dos casos se prefacturan. 5. Doble facturación: dado un contrato ya facturado para 10/2026 secuencia 0, cuando otro lote intenta emitirlo, entonces el índice único de <code>billedPeriods</code> lo impide y el caso queda en excepción <code>PERIOD_ALREADY_BILLED</code>; tras una NC con &quot;permite refacturar&quot;, el período se libera. 6. Reintento del job: dado un bloque emitido cuyo worker cae antes de confirmar progreso, cuando el job se reintenta, entonces no se crean comprobantes duplicados (misma <code>idempotencyKey</code>) y la numeración no tiene huecos. 7. Fallo sistémico: dada la credencial ARCA inválida, cuando se emite, entonces el lote pasa a <code>paused</code> con motivo…</li></ul><h2 id="_3-casos-por-caso-de-uso-cu" tabindex="-1">3. Casos por caso de uso (CU) <a class="header-anchor" href="#_3-casos-por-caso-de-uso-cu" aria-label="Permalink to &quot;3. Casos por caso de uso (CU)&quot;">​</a></h2><p><strong>CP-FAC-8001 — CU-10. Liquidar y facturar un período (BASE §10)</strong></p><ul><li>Cubre: CU-10; M05 §16</li><li>Ola: O4 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</li><li>Dado Consumos aprobados, cuadros vigentes; actor: Responsable de facturación, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando §9.1 pasos 1–12.</li><li>Entonces Comprobantes emitidos y obligaciones en M07. Alternativo o excepción: Excepciones (§9.2), pausa (§9.6).</li></ul><p><strong>CP-FAC-8002 — CU-FAC-01. Emitir lote de facturación (BASE §44)</strong></p><ul><li>Cubre: CU-FAC-01; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</li><li>Dado Lote <code>prebilled</code>; actor: Responsable, aprobador, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando Revisar resumen, aprobar, emitir, seguir progreso.</li><li>Entonces Lote <code>issued</code> o <code>issuedWithPending</code>. Alternativo o excepción: Separación de funciones impide auto-aprobación (403 <code>FAC_SEGREGATION_OF_DUTIES</code>).</li></ul><p><strong>CP-FAC-8003 — CU-LOT-01. Ejecutar lote con excepciones (BASE §69)</strong></p><ul><li>Cubre: CU-LOT-01; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Excepciones: 2 abiertas (ESC-02), 1 resuelta —</li><li>Dado Lote preparado; actor: Responsable, correctores, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando Prefacturar, trabajar la bandeja, reprocesar.</li><li>Entonces Cuadre completo del lote. Alternativo o excepción: Exclusión con causa; traslado al cierre.</li></ul><p><strong>CP-FAC-8004 — CU-103. Facturar agrupado a un titular (BASE §103)</strong></p><ul><li>Cubre: CU-103; M05 §16</li><li>Ola: O4 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</li><li>Dado Grupo <code>active</code> con validación fiscal; actor: Responsable, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando El lote resuelve modalidad agrupada y emite un comprobante con bloques por servicio.</li><li>Entonces Un comprobante, una obligación por servicio. Alternativo o excepción: Periodicidad distinta (PA-FAC-02); PV distintos → excepción <code>MIXED_POS_IN_GROUP</code>.</li></ul><p><strong>CP-FAC-8005 — CU-40. Ejemplo integrado (BASE §40)</strong></p><ul><li>Cubre: CU-40; M05 §16</li><li>Ola: O4 · Prioridad: Núcleo · Tipo: regla</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</li><li>Dado Consumo aprobado; actor: Sistema, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando Emite la factura del ejemplo con sus vencimientos.</li><li>Entonces Factura disponible para cobro.</li></ul><p><strong>CP-FAC-8006 — CU-FAC-02. Configurar ciclo, universo y plantilla</strong></p><ul><li>Cubre: CU-FAC-02; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Universos: <code>GRUPO-CENTRO</code>, <code>GRUPO-NORTE</code>, <code>CONTROL</code> (10 cuentas) <code>GAS-TODOS</code></li><li>Dado actor: Responsable, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando Crear universo, plantilla y ciclo; vista previa de calendario; publicar.</li><li>Entonces Ciclo programado. Alternativo o excepción: Solapamiento de universos → error.</li></ul><p><strong>CP-FAC-8007 — CU-FAC-03. Resolver excepción</strong></p><ul><li>Cubre: CU-FAC-03; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</li><li>Dado Excepción abierta asignada; actor: Corrector, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando Abrir enlace, corregir en el módulo dueño, marcar resuelta, reprocesar.</li><li>Entonces Caso emitido en reproceso. Alternativo o excepción: Corrección insuficiente → la excepción reabre.</li></ul><p><strong>CP-FAC-8008 — CU-FAC-04. Anular o emitir NC/ND</strong></p><ul><li>Cubre: CU-FAC-04; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</li><li>Dado Comprobante emitido; actor: Operador de correcciones, contador, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando §9.3.</li><li>Entonces Comprobante corregido sin borrado. Alternativo o excepción: No anulable → se propone NC; pagos → NC con imputación en M07.</li></ul><p><strong>CP-FAC-8009 — CU-FAC-05. Refacturar un comprobante</strong></p><ul><li>Cubre: CU-FAC-05; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</li><li>Dado Comprobante revertible; actor: Facturación, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando §9.4.</li><li>Entonces NC + nueva factura relacionadas. Alternativo o excepción: Sin reversión previa → bloqueo <code>FAC_PERIOD_ALREADY_BILLED</code>.</li></ul><p><strong>CP-FAC-8010 — CU-FAC-06. Emitir factura manual o replicada</strong></p><ul><li>Cubre: CU-FAC-06; RN-FAC-045; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Tipos: Factura A/B, ND A/B, NC A/B, Liquidación de servicios públicos A/B y créditos, interno X Factura A/B, NC A/B, ND A/B</li><li>Dado Cuenta activa; actor: Operador, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando §9.5.</li><li>Entonces Comprobante individual emitido. Alternativo o excepción: Validaciones RN-FAC-045.</li></ul><p><strong>CP-FAC-8011 — CU-FAC-07. Distribuir comprobantes</strong></p><ul><li>Cubre: CU-FAC-07; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Distribución: 60 % email, 25 % papel por 3 rutas, 15 % WhatsApp; 2 rebotes 100 % email</li><li>Dado Comprobantes autorizados; actor: Operador de distribución, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando §9.7.</li><li>Entonces Entregas registradas. Alternativo o excepción: Rebote → papel.</li></ul><p><strong>CP-FAC-8012 — CU-FAC-08. Cerrar ciclo con acta</strong></p><ul><li>Cubre: CU-FAC-08; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</li><li>Dado Lotes emitidos; actor: Responsable, aprobador, contador, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando Proponer, revisar cuadre, aprobar, descargar acta.</li><li>Entonces Acta inmutable. Alternativo o excepción: Cuadre no balancea → no se puede enviar; reapertura.</li></ul><p><strong>CP-FAC-8013 — CU-FAC-09. Crear o desarmar grupo de facturación</strong></p><ul><li>Cubre: CU-FAC-09; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Grupo de facturación: <code>GF-DEMO-001</code>: titular ficticio con energía, internet y tasa (CU-103) —</li><li>Dado Contratos del mismo titular; actor: Responsable, contador, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando Crear grupo, validar fiscalmente, activar; desarmar desde un período.</li><li>Entonces Grupo versionado. Alternativo o excepción: CUIT distinto → <code>FAC_GROUP_TAXID_MISMATCH</code>.</li></ul><p><strong>CP-FAC-8014 — CU-FAC-10. Recategorizar</strong></p><ul><li>Cubre: CU-FAC-10; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</li><li>Dado Consumos históricos; actor: Operador, aprobador, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando Simular, revisar, confirmar.</li><li>Entonces Categorías actualizadas en M02. Alternativo o excepción: Sin cuadros ENARGAS completos → error.</li></ul><p><strong>CP-FAC-8015 — CU-FAC-11. Aplicar retroactivos</strong></p><ul><li>Cubre: CU-FAC-11; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</li><li>Dado Cuadro nuevo con vigencia pasada; actor: Operador, aprobador, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando Simular diferencias por período y contrato; aprobar; ítems facturables generados.</li><li>Entonces Diferencias en el próximo lote. Alternativo o excepción: Signo del interés (PA-FAC-16).</li></ul><p><strong>CP-FAC-8016 — CU-FAC-12. Modificación masiva</strong></p><ul><li>Cubre: CU-FAC-12; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante agrupado CU-103 ARS 44.200 con pago demo de ARS 30.000 (en M07) 5 facturas…</li><li>Dado Comprobantes no cerrados; actor: Operador, aprobador, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando Filtrar, elegir campos, vista previa, aprobar.</li><li>Entonces Cambios auditados con antes/después. Alternativo o excepción: Autorizados: solo datos no fiscales (PA-FAC-10).</li></ul><p><strong>CP-FAC-8017 — CU-FAC-13. Importar cargos de terceros</strong></p><ul><li>Cubre: CU-FAC-13; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante agrupado CU-103 ARS 44.200 con pago demo de ARS 30.000 (en M07) 5 facturas…</li><li>Dado Archivo de formato soportado; actor: Operador, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando Subir, mapear, validar, confirmar.</li><li>Entonces Ítems facturables o comprobantes. Alternativo o excepción: Filas con error no se aplican.</li></ul><p><strong>CP-FAC-8018 — CU-FAC-14. Bloquear o desbloquear comprobantes</strong></p><ul><li>Cubre: CU-FAC-14; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante agrupado CU-103 ARS 44.200 con pago demo de ARS 30.000 (en M07) 5 facturas…</li><li>Dado Comprobante con saldo; actor: Operador, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando Elegir causa, bloquear; desbloquear.</li><li>Entonces Historial de bloqueo. Alternativo o excepción: Propagación al cierre (PA-FAC-15).</li></ul><p><strong>CP-FAC-8019 — CU-FAC-15. Consultar y descargar mi factura</strong></p><ul><li>Cubre: CU-FAC-15; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante agrupado CU-103 ARS 44.200 con pago demo de ARS 30.000 (en M07) 5 facturas…</li><li>Dado Usuario vinculado a la cuenta; actor: Socio, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando Ver lista, detalle, descargar, pagar.</li><li>Entonces Acceso a sus comprobantes. Alternativo o excepción: Consulta sin login (PRM-FAC-145).</li></ul><p><strong>CP-FAC-8020 — CU-FAC-16. Registrar entrega en reparto</strong></p><ul><li>Cubre: CU-FAC-16; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: integración</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Lotes: <code>LOTE-AG-DEMO-001</code> (100 casos: 98 emitidos, <code>ITEM-099</code> sin CUIT, <code>ITEM-100</code> lectura), <code>LOTE-AG-DEMO-001-R1</code> reproceso <code>LOTE-GAS-DEMO-001</code> simulación</li><li>Dado Ruta asignada; actor: Repartidor, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando Marcar entregado/devuelto (offline), sincronizar.</li><li>Entonces Entregas actualizadas. Alternativo o excepción: Conflicto de sincronización → gana el primer registro, el segundo queda observado.</li></ul><p><strong>CP-FAC-8021 — CU-FAC-17. Configurar formato de código de barras</strong></p><ul><li>Cubre: CU-FAC-17; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Formatos de código: <code>GENERICO_40_43</code>, <code>PAGOFACIL_DEMO</code>, <code>SIRO_56_DEMO</code> con vectores de prueba <code>GENERICO_40_43</code></li><li>Dado actor: Administrador, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando Definir segmentos, DV, decodificador, vectores; publicar; asignar.</li><li>Entonces Formato activo. Alternativo o excepción: Vector falla → no publica.</li></ul><p><strong>CP-FAC-8022 — CU-FAC-18. Generar talón sumado o de cuotas</strong></p><ul><li>Cubre: CU-FAC-18; M05 §16</li><li>Ola: O4 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; semillas de M05 §18.</li><li>Datos de prueba: Comprobantes: <code>FAC-DEMO-001</code> ARS 13.000, Vto1 15-11-2026; <code>FAC-AG-DEMO-002</code> ARS 13.000; <code>FAC-INT-DEMO-002</code> ARS 25.000; <code>RES-DEMO-001</code> ARS 38.000; comprobante agrupado CU-103 ARS 44.200 con pago demo de ARS 30.000 (en M07) 5 facturas…</li><li>Dado Comprobantes con saldo; actor: Operador de distribución, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando Elegir comprobantes, generar, imprimir.</li><li>Entonces Documento de pago con códigos. Alternativo o excepción: Talón anterior vigente → <code>superseded</code>.</li></ul>',98)])])}const m=o(c,[["render",r]]);export{C as __pageData,m as default};
